const SORANET_PRIVACY_TOKEN_HEADER: &str = "x-soranet-privacy-token";

fn privacy_token(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(SORANET_PRIVACY_TOKEN_HEADER)
        .or_else(|| headers.get("x-api-token"))
        .and_then(|value| value.to_str().ok())
}

fn privacy_reject(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> AxResponse {
    let payload = ErrorEnvelope::new(code, message.into());
    (status, utils::NoritoBody(payload)).into_response()
}

async fn enforce_soranet_privacy_ingest(
    app: &SharedAppState,
    headers: &HeaderMap,
    remote: Option<IpAddr>,
    endpoint: &'static str,
) -> Result<(), AxResponse> {
    let ingest_cfg = &app.soranet_privacy_ingest;
    #[cfg(not(feature = "telemetry"))]
    let _ = endpoint;
    if !ingest_cfg.enabled {
        #[cfg(feature = "telemetry")]
        app.telemetry
            .record_soranet_privacy_ingest_reject(endpoint, "disabled")
            .await;
        return Err(privacy_reject(
            StatusCode::SERVICE_UNAVAILABLE,
            "soranet_privacy_disabled",
            "soranet privacy ingestion is disabled",
        ));
    }

    if app.soranet_privacy_allow_nets.is_empty()
        || !limits::is_allowed_by_cidr(headers, remote, &app.soranet_privacy_allow_nets)
    {
        #[cfg(feature = "telemetry")]
        app.telemetry
            .record_soranet_privacy_ingest_reject(endpoint, "namespace_blocked")
            .await;
        return Err(privacy_reject(
            StatusCode::FORBIDDEN,
            "soranet_privacy_namespace_blocked",
            "submitter not in allowed namespace",
        ));
    }

    let token = privacy_token(headers);
    if ingest_cfg.require_token {
        let Some(token_val) = token else {
            #[cfg(feature = "telemetry")]
            app.telemetry
                .record_soranet_privacy_ingest_reject(endpoint, "missing_token")
                .await;
            return Err(privacy_reject(
                StatusCode::UNAUTHORIZED,
                "soranet_privacy_token_required",
                "missing SoraNet privacy token",
            ));
        };
        if !app.soranet_privacy_tokens.contains(token_val) {
            #[cfg(feature = "telemetry")]
            app.telemetry
                .record_soranet_privacy_ingest_reject(endpoint, "invalid_token")
                .await;
            return Err(privacy_reject(
                StatusCode::UNAUTHORIZED,
                "soranet_privacy_token_invalid",
                "token not authorised for SoraNet privacy ingest",
            ));
        }
    }

    let rate_key = token
        .map(ToOwned::to_owned)
        .or_else(|| remote.map(|ip| ip.to_string()))
        .unwrap_or_else(|| "anonymous".to_string());
    let enforce_rate = ingest_cfg.rate_per_sec.is_some();
    if !limits::allow_conditionally(&app.soranet_privacy_rate_limiter, &rate_key, enforce_rate)
        .await
    {
        #[cfg(feature = "telemetry")]
        app.telemetry
            .record_soranet_privacy_ingest_reject(endpoint, "rate_limited")
            .await;
        return Err(privacy_reject(
            StatusCode::TOO_MANY_REQUESTS,
            "soranet_privacy_rate_limited",
            "soranet privacy ingest is rate limited",
        ));
    }

    Ok(())
}

#[cfg(all(feature = "app_api", feature = "push"))]
fn push_error_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> AxResponse {
    let payload = ErrorEnvelope::new(code, message.into());
    (status, utils::NoritoBody(payload)).into_response()
}

#[cfg(all(feature = "app_api", feature = "push"))]
async fn handler_push_register_device(
    State(app): State<SharedAppState>,
    method: HttpMethod,
    uri: axum::http::Uri,
    headers: HeaderMap,
    crate::utils::extractors::NoritoJsonWithBytes {
        value: mut req,
        raw,
    }: crate::utils::extractors::NoritoJsonWithBytes<push::RegisterDeviceRequest>,
) -> AxResponse {
    let account_id = match push_authorize_device_request(
        &app,
        &method,
        &uri,
        &headers,
        raw.as_ref(),
        &req.account_id,
    ) {
        Ok(account_id) => account_id,
        Err(response) => return response,
    };
    req.account_id = account_id.to_string();
    let rate_key = format!("push:{}", req.account_id);
    if !app.push_rate_limiter.allow(&rate_key).await {
        return push_error_response(
            StatusCode::TOO_MANY_REQUESTS,
            "push_rate_limited",
            "push registrations are rate limited",
        );
    }
    let bridge = app.push.as_ref().expect("checked push presence");
    match bridge.register_device(req) {
        Ok(()) => StatusCode::ACCEPTED.into_response(),
        Err(push::PushError::Disabled) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_disabled",
            "push bridge disabled",
        ),
        Err(push::PushError::MissingCredentials { platform }) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_missing_credentials",
            format!("missing credentials for {}", platform.label()),
        ),
        Err(push::PushError::InvalidAccount(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_account",
            format!("invalid account id `{value}`"),
        ),
        Err(push::PushError::InvalidPlatform(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_platform",
            format!("unsupported platform `{value}`"),
        ),
        Err(push::PushError::TooManyTopics { max }) => push_error_response(
            StatusCode::BAD_REQUEST,
            "too_many_topics",
            format!("topics exceed configured maximum ({max})"),
        ),
        Err(push::PushError::EmptyToken) => push_error_response(
            StatusCode::BAD_REQUEST,
            "empty_token",
            "token must not be empty",
        ),
        Err(push::PushError::InvalidEnvironment(value)) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_invalid_environment",
            format!("unsupported APNs environment `{value}`"),
        ),
        Err(push::PushError::Storage(value)) => push_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "push_storage_error",
            value,
        ),
    }
}

#[cfg(all(feature = "app_api", feature = "push"))]
async fn handler_push_unregister_device(
    State(app): State<SharedAppState>,
    method: HttpMethod,
    uri: axum::http::Uri,
    headers: HeaderMap,
    crate::utils::extractors::NoritoJsonWithBytes {
        value: mut req,
        raw,
    }: crate::utils::extractors::NoritoJsonWithBytes<push::UnregisterDeviceRequest>,
) -> AxResponse {
    let account_id = match push_authorize_device_request(
        &app,
        &method,
        &uri,
        &headers,
        raw.as_ref(),
        &req.account_id,
    ) {
        Ok(account_id) => account_id,
        Err(response) => return response,
    };
    req.account_id = account_id.to_string();
    let bridge = app.push.as_ref().expect("checked push presence");
    match bridge.unregister_device(req) {
        Ok(()) => StatusCode::ACCEPTED.into_response(),
        Err(push::PushError::Disabled) => push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_disabled",
            "push bridge disabled",
        ),
        Err(push::PushError::InvalidAccount(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_account",
            format!("invalid account id `{value}`"),
        ),
        Err(push::PushError::InvalidPlatform(value)) => push_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_platform",
            format!("unsupported platform `{value}`"),
        ),
        Err(push::PushError::EmptyToken) => push_error_response(
            StatusCode::BAD_REQUEST,
            "empty_token",
            "token must not be empty",
        ),
        Err(push::PushError::Storage(value)) => push_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "push_storage_error",
            value,
        ),
        Err(push::PushError::MissingCredentials { .. })
        | Err(push::PushError::TooManyTopics { .. })
        | Err(push::PushError::InvalidEnvironment(_)) => StatusCode::ACCEPTED.into_response(),
    }
}

#[cfg(all(feature = "app_api", feature = "push"))]
fn push_authorize_device_request(
    app: &SharedAppState,
    method: &HttpMethod,
    uri: &axum::http::Uri,
    headers: &HeaderMap,
    body: &[u8],
    account_literal: &str,
) -> Result<AccountId, AxResponse> {
    if app.push.is_none() {
        return Err(push_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "push_disabled",
            "push bridge disabled",
        ));
    }
    let account_id = match routing::parse_account_literal_with_state(
        app.state.as_ref(),
        account_literal,
        &app.telemetry,
        "/v1/notify/devices",
    ) {
        Ok((account_id, _)) => account_id,
        Err(_) => {
            return Err(push_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_account",
                format!("invalid account id `{}`", account_literal.trim()),
            ));
        }
    };
    match crate::app_auth::verify_canonical_request(
        &app.state,
        headers,
        method,
        uri,
        body,
        Some(&account_id),
    ) {
        Ok(Some(_)) => Ok(account_id),
        Ok(None) => Err(push_error_response(
            StatusCode::UNAUTHORIZED,
            "push_auth_required",
            "signed account headers are required",
        )),
        Err(error) => Err(push_auth_error_response(error)),
    }
}

#[cfg(all(feature = "app_api", feature = "push"))]
fn push_auth_error_response(error: Error) -> AxResponse {
    if let Error::Query(iroha_data_model::ValidationFail::NotPermitted(message)) = &error
        && message.contains("does not match")
    {
        return push_error_response(
            StatusCode::FORBIDDEN,
            "push_account_mismatch",
            "signed account does not match device account",
        );
    }
    push_error_response(
        StatusCode::UNAUTHORIZED,
        "push_auth_invalid",
        error.to_string(),
    )
}

async fn check_proof_access(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    cost: u64,
    enforce_rate: bool,
) -> Result<(), Error> {
    check_access_enforced(app, headers, remote, hint, enforce_rate).await?;
    let key = rate_limit_key(headers, remote, hint, app.api_token_enforced());
    if limits::allow_cost_conditionally(&app.proof_rate_limiter, &key, cost, enforce_rate).await {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    app.telemetry.with_metrics(|tel| {
        tel.observe_torii_proof_request(hint, "rate_limited", 0, std::time::Duration::from_secs(0))
    });
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    iroha_logger::warn!(
        %hint,
        %retry_after_secs,
        %key,
        "proof endpoint throttled request"
    );
    Err(Error::ProofRateLimited {
        endpoint: hint,
        retry_after_secs,
    })
}

// The proof API rate configuration is expressed in requests per minute with a
// request burst. Body bytes are bounded separately by `max_body_bytes`.
const PROOF_REQUEST_RATE_COST: u64 = 1;

async fn collect_proof_body_with_deadline(
    request: axum::http::Request<Body>,
    max_bytes: usize,
    deadline: Duration,
) -> Result<axum::http::Request<Body>, Response> {
    let (parts, body) = request.into_parts();
    let bytes = match tokio::time::timeout(deadline, axum::body::to_bytes(body, max_bytes)).await {
        Ok(Ok(bytes)) => bytes,
        Ok(Err(error)) => {
            let mut source: Option<&(dyn std::error::Error + 'static)> = Some(&error);
            let mut length_limited = false;
            while let Some(current) = source {
                if current.is::<http_body_util::LengthLimitError>() {
                    length_limited = true;
                    break;
                }
                source = current.source();
            }
            let (status, message) = if length_limited {
                (
                    StatusCode::PAYLOAD_TOO_LARGE,
                    "proof request body exceeds the configured byte limit",
                )
            } else {
                iroha_logger::warn!(%error, "failed to read proof request body stream");
                (
                    StatusCode::BAD_REQUEST,
                    "proof request body stream ended with a protocol error",
                )
            };
            return Err((status, message).into_response());
        }
        Err(_) => {
            return Err((
                StatusCode::REQUEST_TIMEOUT,
                "proof request body was not completed before the absolute read deadline",
            )
                .into_response());
        }
    };
    Ok(axum::http::Request::from_parts(parts, Body::from(bytes)))
}

async fn proof_body_admission_middleware(
    State(app): State<SharedAppState>,
    request: axum::http::Request<Body>,
    next: Next,
) -> Response {
    let permit = match app.proof_body_inflight.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(_) => {
            return Error::ProofRateLimited {
                endpoint: "proof request body admission",
                retry_after_secs: app.proof_limits.retry_after.as_secs().max(1),
            }
            .into_response();
        }
    };
    let max_bytes = usize::try_from(app.proof_limits.max_body_bytes).unwrap_or(usize::MAX);
    let request = match collect_proof_body_with_deadline(
        request,
        max_bytes,
        app.proof_limits.body_read_timeout,
    )
    .await
    {
        Ok(request) => request,
        Err(response) => {
            drop(permit);
            return response;
        }
    };
    let response = next.run(request).await;
    drop(permit);
    response
}

fn proof_post_router_with_body_limits(
    router: Router<SharedAppState>,
    state: SharedAppState,
) -> Router<SharedAppState> {
    let body_limit = DefaultBodyLimit::max(
        usize::try_from(state.proof_limits.max_body_bytes).unwrap_or(usize::MAX),
    );
    let admission = axum::middleware::from_fn_with_state(state, proof_body_admission_middleware);
    // The admission middleware is outermost, so aggregate capacity is acquired
    // before Axum buffers/extracts each request body.
    router.layer(body_limit).layer(admission)
}

fn enforce_proof_body_limit(app: &AppState, len: usize, hint: &'static str) -> Result<(), Error> {
    let max = app.proof_limits.max_body_bytes;
    if (len as u64) <= max {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
            "payload too large for {hint}: {len} > {max}"
        )),
    )))
}

fn require_proof_json_content_type(
    headers: &axum::http::HeaderMap,
    hint: &'static str,
) -> Result<(), Error> {
    let content_type = headers
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .map(str::trim);
    if content_type.is_some_and(|value| value.eq_ignore_ascii_case("application/json")) {
        return Ok(());
    }
    Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
            "{hint} requires Content-Type: application/json"
        )),
    )))
}

async fn enforce_proof_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    bytes: u64,
    enforce_rate: bool,
) -> Result<(), Error> {
    if bytes == 0 {
        return Ok(());
    }
    let key = rate_limit_key(headers, remote, hint, app.api_token_enforced());
    if limits::allow_cost_conditionally(&app.proof_egress_limiter, &key, bytes, enforce_rate).await
    {
        return Ok(());
    }
    app.telemetry
        .with_metrics(|tel| tel.inc_torii_proof_throttle(hint));
    let retry_after_secs = app.proof_limits.retry_after.as_secs().max(1);
    iroha_logger::warn!(
        %hint,
        %retry_after_secs,
        %key,
        bytes,
        "proof endpoint egress throttled request"
    );
    Err(Error::ProofRateLimited {
        endpoint: hint,
        retry_after_secs,
    })
}

/// Charge the exact bytes of an internally buffered proof response before it
/// is handed to Hyper. Collecting here also makes the accounting invariant
/// independent of HTTP body size-hint implementations.
async fn proof_response_with_exact_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    response: axum::response::Response,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error> {
    let (parts, body) = response.into_parts();
    let body = axum::body::to_bytes(body, usize::MAX).await.map_err(|error| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
            "failed to collect buffered {hint} proof response for exact egress accounting: {error}"
        )))
    })?;
    enforce_proof_egress(
        app,
        headers,
        remote,
        hint,
        u64::try_from(body.len()).unwrap_or(u64::MAX),
        enforce_rate,
    )
    .await?;
    Ok(axum::response::Response::from_parts(
        parts,
        axum::body::Body::from(body),
    ))
}

async fn proof_json_response_with_egress<T>(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    payload: T,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error>
where
    T: JsonSerialize,
{
    // Serialize exactly once so the charged byte count is identical to the
    // response body sent to the client.
    let body = norito::json::to_vec(&payload).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    enforce_proof_egress(app, headers, remote, hint, body.len() as u64, enforce_rate).await?;

    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(response)
}

async fn proof_cached_json_response_with_egress(
    app: &AppState,
    headers: &axum::http::HeaderMap,
    remote: Option<IpAddr>,
    hint: &'static str,
    body: Bytes,
    enforce_rate: bool,
) -> Result<axum::response::Response, Error> {
    // Charge the immutable cached representation before the cheap ref-counted
    // clone is handed to Axum. Concurrent GETs therefore cannot duplicate a
    // multi-megabyte proved payload in process memory.
    enforce_proof_egress(app, headers, remote, hint, body.len() as u64, enforce_rate).await?;
    let mut response = axum::response::Response::new(axum::body::Body::from(body));
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/json"),
    );
    Ok(response)
}

