#[cfg(feature = "app_api")]
fn parse_account_id_for_endpoint(
    app: &AppState,
    literal: &str,
    endpoint: &'static str,
) -> Result<AccountId, Error> {
    routing::parse_account_path_segment_with_state(
        app.state.as_ref(),
        literal,
        &app.telemetry,
        endpoint,
    )
    .map(|(account_id, _)| account_id.into())
}

#[cfg(feature = "app_api")]
fn normalize_identifier_input(
    policy: &iroha_data_model::identifier::IdentifierPolicy,
    raw: &str,
) -> Result<String, Error> {
    policy.normalization.normalize(raw).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
        ))
    })
}

#[cfg(feature = "app_api")]
fn identifier_normalization_label(
    normalization: iroha_data_model::identifier::IdentifierNormalization,
) -> &'static str {
    match normalization {
        iroha_data_model::identifier::IdentifierNormalization::Exact => "exact",
        iroha_data_model::identifier::IdentifierNormalization::LowercaseTrimmed => {
            "lowercase_trimmed"
        }
        iroha_data_model::identifier::IdentifierNormalization::PhoneE164 => "phone_e164",
        iroha_data_model::identifier::IdentifierNormalization::EmailAddress => "email_address",
        iroha_data_model::identifier::IdentifierNormalization::AccountNumber => "account_number",
    }
}

#[cfg(feature = "app_api")]
fn identifier_conversion_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::Conversion(message.into()),
    ))
}

#[cfg(feature = "app_api")]
fn identifier_internal_error(message: impl Into<String>) -> Error {
    Error::Query(iroha_data_model::ValidationFail::InternalError(
        message.into(),
    ))
}

#[cfg(feature = "app_api")]
fn parse_encrypted_identifier_ciphertext(
    raw: &str,
) -> Result<iroha_crypto::BfvIdentifierCiphertext, Error> {
    let literal = raw.trim();
    if literal.is_empty() {
        return Err(identifier_conversion_error(
            "encrypted identifier ciphertext must not be empty",
        ));
    }
    let bytes = hex::decode(literal.trim_start_matches("0x")).map_err(|err| {
        identifier_conversion_error(format!(
            "encrypted identifier ciphertext is not valid hex: {err}"
        ))
    })?;
    norito::decode_from_bytes::<iroha_crypto::BfvIdentifierCiphertext>(&bytes).map_err(|err| {
        identifier_conversion_error(format!(
            "encrypted identifier ciphertext is not valid Norito BFV data: {err}"
        ))
    })
}

#[cfg(feature = "app_api")]
fn parse_hex_bytes(raw: &str, field_name: &str) -> Result<Vec<u8>, Error> {
    let literal = raw.trim();
    if literal.is_empty() {
        return Err(identifier_conversion_error(format!(
            "{field_name} must not be empty"
        )));
    }
    hex::decode(literal.trim_start_matches("0x"))
        .map_err(|err| identifier_conversion_error(format!("{field_name} is not valid hex: {err}")))
}

#[cfg(feature = "app_api")]
fn ram_lfe_verification_mode_label(mode: iroha_crypto::RamLfeVerificationMode) -> &'static str {
    match mode {
        iroha_crypto::RamLfeVerificationMode::Signed => "signed",
        iroha_crypto::RamLfeVerificationMode::Proof => "proof",
    }
}

#[cfg(feature = "app_api")]
fn derive_ram_lfe_request_draft(
    resolver: &identifier_resolution::IdentifierResolutionService,
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
    request: &routing::RamLfeExecuteRequestDto,
) -> Result<identifier_resolution::RamLfeExecutionDraft, Error> {
    let ciphertext = parse_encrypted_identifier_ciphertext(&request.encrypted_input)?;
    resolver
        .execute_encrypted(program_policy, &ciphertext)
        .map_err(|err| match err {
            identifier_resolution::IdentifierResolutionError::InvalidUtf8 => {
                identifier_conversion_error(err.to_string())
            }
            _ => identifier_internal_error(err.to_string()),
        })
}

#[cfg(feature = "app_api")]
fn derive_identifier_request_draft(
    resolver: &identifier_resolution::IdentifierResolutionService,
    policy: &iroha_data_model::identifier::IdentifierPolicy,
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
    request: &routing::IdentifierResolveRequestDto,
) -> Result<identifier_resolution::IdentifierResolutionDraft, Error> {
    let ciphertext = parse_encrypted_identifier_ciphertext(&request.encrypted_input)?;
    match program_policy.commitment.backend {
        iroha_crypto::RamLfeBackend::BfvAffineSha3_256V1
        | iroha_crypto::RamLfeBackend::BfvProgrammedSha3_256V1 => resolver
            .derive_encrypted(
                policy,
                program_policy,
                &ciphertext,
                request.output_opening.clone(),
            )
            .map_err(|err| identifier_internal_error(err.to_string())),
        _ => Err(identifier_conversion_error(
            "identifier encrypted input requires a BFV-backed RAM-LFE program",
        )),
    }
}

#[cfg(feature = "app_api")]
fn ram_lfe_proof_verifier_metadata_dto(
    verifier: Option<&iroha_crypto::RamLfeProofVerifierMetadata>,
) -> Option<routing::RamLfeProofVerifierMetadataDto> {
    verifier.map(|metadata| routing::RamLfeProofVerifierMetadataDto {
        proof_backend: metadata.proof_backend.clone(),
        circuit_id: metadata.circuit_id.clone(),
        public_inputs_schema_hash: metadata.public_inputs_schema_hash.to_string(),
        verifying_key_bytes_b64: BASE64_STANDARD.encode(&metadata.verifying_key_bytes),
    })
}

#[cfg(feature = "app_api")]
fn ram_lfe_execution_receipt_payload_dto(
    payload: &iroha_data_model::ram_lfe::RamLfeExecutionReceiptPayload,
) -> routing::RamLfeExecutionReceiptPayloadDto {
    routing::RamLfeExecutionReceiptPayloadDto {
        program_id: payload.program_id.to_string(),
        program_digest: payload.program_digest.to_string(),
        backend: payload.backend.as_str().to_owned(),
        verification_mode: ram_lfe_verification_mode_label(payload.verification_mode).to_owned(),
        input_ciphertext_hash: payload.input_ciphertext_hash.to_string(),
        output_ciphertext_hash: payload.output_ciphertext_hash.to_string(),
        parameter_digest: payload.parameter_digest.to_string(),
        evaluation_key_digest: payload.evaluation_key_digest.to_string(),
        output_hash: payload.output_hash.to_string(),
        associated_data_hash: payload.associated_data_hash.to_string(),
        executed_at_ms: payload.executed_at_ms,
        expires_at_ms: payload.expires_at_ms,
    }
}

#[cfg(feature = "app_api")]
fn ram_lfe_receipt_attestation_dto(
    attestation: &iroha_data_model::ram_lfe::RamLfeReceiptAttestation,
) -> routing::RamLfeReceiptAttestationDto {
    match attestation {
        iroha_data_model::ram_lfe::RamLfeReceiptAttestation::Signed(signature) => {
            routing::RamLfeReceiptAttestationDto {
                kind: "signed".to_owned(),
                signature: Some(hex::encode_upper(signature.payload())),
                proof_backend: None,
                proof_b64: None,
            }
        }
        iroha_data_model::ram_lfe::RamLfeReceiptAttestation::Proof(proof) => {
            routing::RamLfeReceiptAttestationDto {
                kind: "proof".to_owned(),
                signature: None,
                proof_backend: Some(proof.backend.to_string()),
                proof_b64: Some(BASE64_STANDARD.encode(&proof.bytes)),
            }
        }
    }
}

