#[cfg(feature = "app_api")]
fn ram_lfe_program_policy_summary_dto(
    program_policy: &iroha_data_model::ram_lfe::RamLfeProgramPolicy,
) -> routing::RamLfeProgramPolicySummaryDto {
    let public_parameters =
        identifier_resolution::decode_bfv_public_parameters(program_policy).ok();
    let ram_fhe_profile = identifier_resolution::decode_ram_fhe_profile(program_policy)
        .ok()
        .flatten();
    routing::RamLfeProgramPolicySummaryDto {
        program_id: program_policy.program_id.to_string(),
        owner: program_policy.owner.to_string(),
        active: program_policy.active,
        resolver_public_key: program_policy.resolver_public_key.to_string(),
        output_opening_public_key: program_policy.output_opening_public_key.to_string(),
        backend: program_policy.commitment.backend.as_str().to_owned(),
        verification_mode: ram_lfe_verification_mode_label(program_policy.verification_mode)
            .to_owned(),
        input_encryption: public_parameters.as_ref().map(|_| "bfv-v1".to_owned()),
        input_encryption_public_parameters: public_parameters
            .as_ref()
            .and_then(|value| norito::to_bytes(value).ok())
            .map(hex::encode_upper),
        input_encryption_public_parameters_decoded: public_parameters,
        ram_fhe_profile,
        proof_verifier: ram_lfe_proof_verifier_metadata_dto(
            identifier_resolution::decode_programmed_public_parameters(program_policy)
                .ok()
                .flatten()
                .and_then(|parameters| parameters.proof_verifier)
                .as_ref(),
        ),
        note: program_policy.note.clone(),
    }
}

#[cfg(feature = "app_api")]
fn identifier_policy_summary_dto(
    policy: &iroha_data_model::identifier::IdentifierPolicy,
    program_policy: Option<&iroha_data_model::ram_lfe::RamLfeProgramPolicy>,
) -> routing::IdentifierPolicySummaryDto {
    let public_parameters = program_policy
        .and_then(|policy| identifier_resolution::decode_bfv_public_parameters(policy).ok());
    let ram_fhe_profile = program_policy
        .and_then(|policy| identifier_resolution::decode_ram_fhe_profile(policy).ok())
        .flatten();
    routing::IdentifierPolicySummaryDto {
        policy_id: policy.id.to_string(),
        program_id: policy.program_id.to_string(),
        owner: policy.owner.to_string(),
        active: policy.active,
        normalization: identifier_normalization_label(policy.normalization).to_owned(),
        resolver_public_key: program_policy
            .map(|policy| policy.resolver_public_key.to_string())
            .unwrap_or_default(),
        output_opening_public_key: program_policy
            .map(|policy| policy.output_opening_public_key.to_string())
            .unwrap_or_default(),
        backend: program_policy
            .map(|policy| policy.commitment.backend.as_str().to_owned())
            .unwrap_or_default(),
        input_encryption: public_parameters.as_ref().map(|_| "bfv-v1".to_owned()),
        input_encryption_public_parameters: public_parameters
            .as_ref()
            .and_then(|value| norito::to_bytes(value).ok())
            .map(hex::encode_upper),
        input_encryption_public_parameters_decoded: public_parameters,
        ram_fhe_profile,
        proof_verifier: program_policy.and_then(|program_policy| {
            ram_lfe_proof_verifier_metadata_dto(
                identifier_resolution::decode_programmed_public_parameters(program_policy)
                    .ok()
                    .flatten()
                    .and_then(|parameters| parameters.proof_verifier)
                    .as_ref(),
            )
        }),
        note: policy.note.clone(),
    }
}

