#[cfg(feature = "app_api")]
async fn execute_torii_read_via_proxy(
    app: &SharedAppState,
    routing_decision: RoutingDecision,
    request: ToriiReadProxyRequestV1,
) -> Response {
    execute_torii_proxy_request_with_fallback(
        app,
        routing_decision,
        ToriiProxyRequestKindV1::Read(request),
    )
    .await
}

#[cfg(feature = "app_api")]
async fn execute_torii_read_for_route(
    app: &SharedAppState,
    routing_decision: RoutingDecision,
    request: ToriiReadProxyRequestV1,
) -> Response {
    if let Some(upstream_url) = app
        .public_dataspace_upstreams
        .get(&routing_decision.dataspace_id)
        .cloned()
    {
        return execute_torii_read_via_public_dataspace_upstream(
            upstream_url,
            routing_decision,
            request,
        )
        .await;
    }

    if should_execute_route_locally(app.as_ref(), routing_decision) {
        execute_torii_read_request_locally(app, request, routing_decision, "local").await
    } else {
        execute_torii_read_via_proxy(app, routing_decision, request).await
    }
}

#[cfg(feature = "app_api")]
fn torii_internal_query_authority(
    app: &SharedAppState,
    routing_decision: RoutingDecision,
) -> Option<AccountId> {
    let view = app.state.world_view();
    for (account_id, _) in view.accounts().iter() {
        if torii_target_account_routes(app.as_ref(), account_id)
            .ok()
            .is_some_and(|routes| routes.contains(&routing_decision))
        {
            return Some(account_id.clone());
        }
    }
    view.accounts()
        .iter()
        .next()
        .map(|(account_id, _)| account_id.clone())
}

#[cfg(feature = "app_api")]
fn torii_validation_fail_is_missing_proof_record(fail: &iroha_data_model::ValidationFail) -> bool {
    matches!(
        fail,
        iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(message)
        ) if message == "ProofRecord not found"
    )
}

#[cfg(feature = "app_api")]
async fn normalize_torii_proof_record_query_response(response: Response) -> Response {
    if response.status() != StatusCode::BAD_REQUEST {
        return response;
    }

    let (parts, body) = response.into_parts();
    let body = match axum::body::to_bytes(body, usize::MAX).await {
        Ok(body) => body,
        Err(error) => {
            return torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "invalid_proxy_response",
                format!("failed to read proof query error response: {error}"),
            );
        }
    };

    let missing_proof_record =
        match norito::decode_from_bytes::<iroha_data_model::ValidationFail>(&body) {
            Ok(validation) => torii_validation_fail_is_missing_proof_record(&validation),
            Err(_) => norito::decode_from_bytes::<ErrorEnvelope>(&body)
                .map(|envelope| envelope.message.contains("ProofRecord not found"))
                .unwrap_or(false),
        };

    if missing_proof_record {
        return (
            StatusCode::NOT_FOUND,
            utils::NoritoBody(ErrorEnvelope::new(
                "proof_record_not_found",
                "ProofRecord not found",
            )),
        )
            .into_response();
    }

    Response::from_parts(parts, Body::from(body))
}

#[cfg(feature = "app_api")]
async fn execute_torii_proof_record_get_query(
    app: &SharedAppState,
    proof_id: String,
    routing_decision: RoutingDecision,
    routed_by: &'static str,
) -> Response {
    use iroha_data_model::proof::ProofId;
    use iroha_data_model::query::{
        QueryRequest, SingularQueryOutputBox, prelude::SingularQueryBox,
        proof::prelude::FindProofRecordById,
    };

    let raw_proof_id = proof_id;
    let proof_id = match raw_proof_id.parse::<ProofId>() {
        Ok(proof_id) => proof_id,
        Err(error) => {
            let mut response = torii_proxy_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_proof_id",
                format!("failed to parse proof id `{raw_proof_id}`: {error}"),
            );
            insert_routing_headers(&mut response, routing_decision, routed_by);
            return response;
        }
    };
    let Some(authority) = torii_internal_query_authority(app, routing_decision) else {
        return finish_torii_read_result(
            routing::handle_get_proof_record(app.state.clone(), AxPath(raw_proof_id)).await,
            routing_decision,
            routed_by,
        );
    };
    let request =
        QueryRequest::Singular(SingularQueryBox::FindProofRecordById(FindProofRecordById {
            id: proof_id,
        }))
        .with_authority(authority);

    let mut response =
        match execute_torii_verified_query_exhaustive_for_route(app, request, routing_decision)
            .await
        {
            Ok(iroha_data_model::query::QueryResponse::Singular(
                SingularQueryOutputBox::ProofRecord(record),
            )) => crate::utils::NoritoBody(record).into_response(),
            Ok(iroha_data_model::query::QueryResponse::Singular(_)) => torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "invalid_proxy_response",
                "internal proof query returned an unexpected singular variant",
            ),
            Ok(iroha_data_model::query::QueryResponse::Iterable(_)) => torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "invalid_proxy_response",
                "internal proof query returned an unexpected iterable variant",
            ),
            Err(response) => normalize_torii_proof_record_query_response(response).await,
        };
    insert_routing_headers(&mut response, routing_decision, routed_by);
    response
}

fn routed_by_for_routes(app: &SharedAppState, routes: &[RoutingDecision]) -> &'static str {
    if !routes.is_empty()
        && routes
            .iter()
            .all(|route| should_execute_route_locally(app.as_ref(), *route))
    {
        "local"
    } else {
        "proxy"
    }
}

#[cfg(feature = "app_api")]
async fn execute_torii_fanout_json_payloads_resolved_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    endpoint: ToriiReadEndpointV1,
    path_args: Vec<String>,
    query_string: Option<String>,
    body: Vec<u8>,
) -> Result<
    (
        Vec<RoutingDecision>,
        Vec<Value>,
        ToriiFanoutDiagnostics,
        &'static str,
    ),
    Response,
> {
    if routes.is_empty() {
        return Err(with_torii_fanout_headers(
            torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                "no Nexus dataspace routes are configured",
            ),
            ToriiFanoutDiagnostics::default(),
        ));
    }
    let routed_by = routed_by_for_routes(app, &routes);

    let collected = collect_torii_routed_list_json_payloads(&routes, |route| {
        execute_torii_read_for_route(
            app,
            route,
            torii_read_request(
                endpoint,
                route,
                path_args.clone(),
                query_string.clone(),
                body.clone(),
            ),
        )
    })
    .await?;

    let payloads =
        filter_non_authoritative_global_list_rows(app.as_ref(), endpoint, collected.payloads)?;
    let payloads =
        filter_non_authoritative_global_portfolio_rows(app.as_ref(), endpoint, payloads)?;
    let routes = payloads.iter().map(|(route, _)| *route).collect();
    let payloads = payloads.into_iter().map(|(_, payload)| payload).collect();

    Ok((routes, payloads, collected.diagnostics, routed_by))
}

#[cfg(feature = "app_api")]
fn merge_with_torii_fanout_headers<F>(diagnostics: ToriiFanoutDiagnostics, merge: F) -> Response
where
    F: FnOnce() -> Result<Response, Response>,
{
    match merge() {
        Ok(response) | Err(response) => with_torii_fanout_headers(response, diagnostics),
    }
}

#[cfg(feature = "app_api")]
fn torii_read_fanout_request(
    endpoint: ToriiReadEndpointV1,
    route_scope: ToriiFanoutRouteScopeV1,
    merge: ToriiReadFanoutMergeV1,
    path_args: Vec<String>,
    query_string: Option<String>,
    body: Vec<u8>,
    response_format: ToriiProxyResponseFormatV1,
) -> ToriiReadFanoutProxyRequestV1 {
    ToriiReadFanoutProxyRequestV1 {
        endpoint,
        route_scope,
        merge,
        path_args,
        query_string,
        body,
        response_format,
    }
}

#[cfg(feature = "app_api")]
async fn resolve_torii_proof_record_for_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    proof_id: String,
) -> Result<(ProofRecord, ToriiFanoutDiagnostics, &'static str), Response> {
    if routes.is_empty() {
        return Err(with_torii_fanout_headers(
            torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                "no Nexus dataspace routes are configured",
            ),
            ToriiFanoutDiagnostics::default(),
        ));
    }

    let routed_by = routed_by_for_routes(app, &routes);
    let mut payloads = Vec::with_capacity(routes.len());
    let mut diagnostics = ToriiFanoutDiagnostics::default();
    let mut last_not_found = None;
    let mut last_route_unavailable = None;

    if let Ok(record) =
        routing::handle_get_proof_record(app.state.clone(), AxPath(proof_id.clone())).await
    {
        payloads.push(record.0);
    }

    for _ in &routes {
        diagnostics.record_attempt();
    }
    let responses = futures_util::future::join_all(routes.iter().map(|route| {
        execute_torii_single_route_read(
            app,
            *route,
            ToriiReadEndpointV1::ProofRecordGet,
            vec![proof_id.clone()],
            None,
            Vec::new(),
        )
    }))
    .await;

    for response in responses {
        if response.status() == StatusCode::NOT_FOUND {
            diagnostics.record_skipped_response(&response);
            last_not_found = Some(response);
            continue;
        }
        if torii_response_has_reject_code(&response, "route_unavailable") {
            diagnostics.record_skipped_response(&response);
            last_route_unavailable = Some(response);
            continue;
        }
        match torii_norito_body::<ProofRecord>(response, "proof record response").await {
            Ok(payload) => {
                diagnostics.record_success();
                payloads.push(payload);
            }
            Err(response) => {
                diagnostics.record_skipped_response(&response);
                return Err(with_torii_fanout_headers(response, diagnostics));
            }
        }
    }

    if payloads.is_empty() {
        let response = last_not_found.unwrap_or_else(|| {
            last_route_unavailable.unwrap_or_else(|| {
                torii_proxy_error_response(
                    StatusCode::NOT_FOUND,
                    "not_found",
                    "no dataspace returned a matching result",
                )
            })
        });
        return Err(with_torii_fanout_headers(response, diagnostics));
    }

    let mut unique_payloads = BTreeMap::<Vec<u8>, ProofRecord>::new();
    for payload in payloads {
        let key = match canonical_norito_bytes(&payload) {
            Ok(key) => key,
            Err(response) => return Err(with_torii_fanout_headers(response, diagnostics)),
        };
        unique_payloads.entry(key).or_insert(payload);
    }

    match unique_payloads.len() {
        1 => Ok((
            unique_payloads
                .into_values()
                .next()
                .expect("singleton map length should be one"),
            diagnostics,
            routed_by,
        )),
        _ => Err(with_torii_fanout_headers(
            torii_proxy_error_response(
                StatusCode::CONFLICT,
                "route_conflict",
                "multiple dataspaces returned conflicting singleton results",
            ),
            diagnostics,
        )),
    }
}

#[cfg(feature = "app_api")]
async fn execute_torii_account_read_for_resolved_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    canonical_account_id: String,
    format: ResponseFormat,
) -> Response {
    if routes.is_empty() {
        return with_torii_fanout_headers(
            torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                "no Nexus dataspace routes are configured",
            ),
            ToriiFanoutDiagnostics::default(),
        );
    }

    let mut payloads = Vec::new();
    let mut diagnostics = ToriiFanoutDiagnostics::default();
    let mut last_not_found = None;
    let mut last_route_unavailable = None;
    for route in &routes {
        diagnostics.record_attempt();
        let response = execute_torii_single_route_read(
            app,
            *route,
            ToriiReadEndpointV1::AccountGet,
            vec![canonical_account_id.clone()],
            None,
            Vec::new(),
        )
        .await;
        if response.status() == StatusCode::NOT_FOUND {
            diagnostics.record_skipped_response(&response);
            last_not_found = Some(response);
            continue;
        }
        if torii_response_has_reject_code(&response, "route_unavailable") {
            diagnostics.record_skipped_response(&response);
            last_route_unavailable = Some(response);
            continue;
        }
        match torii_json_body::<AccountReadResponse>(response, "account get response").await {
            Ok(payload) => {
                diagnostics.record_success();
                payloads.push(payload);
            }
            Err(response) => {
                diagnostics.record_skipped_response(&response);
                return with_torii_fanout_headers(response, diagnostics);
            }
        }
    }

    if payloads.is_empty() {
        let response = last_not_found.unwrap_or_else(|| {
            last_route_unavailable.unwrap_or_else(|| {
                torii_proxy_error_response(
                    StatusCode::NOT_FOUND,
                    "not_found",
                    "no dataspace returned a matching result",
                )
            })
        });
        return with_torii_fanout_headers(response, diagnostics);
    }

    merge_with_torii_fanout_headers(diagnostics, || {
        merged_account_read_response(payloads, format, routed_by_for_routes(app, &routes))
    })
}

#[cfg(feature = "app_api")]
fn account_history_payload_has_more(payload: &Value, item_count: usize, page_limit: u64) -> bool {
    payload
        .as_object()
        .and_then(|object| object.get("has_more"))
        .and_then(Value::as_bool)
        .unwrap_or_else(|| u64::try_from(item_count).unwrap_or(u64::MAX) >= page_limit)
}

#[cfg(feature = "app_api")]
async fn execute_torii_account_history_read_for_resolved_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    path_args: Vec<String>,
    query_string: Option<String>,
) -> Response {
    if routes.is_empty() {
        return with_torii_fanout_headers(
            torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                "no Nexus dataspace routes are configured",
            ),
            ToriiFanoutDiagnostics::default(),
        );
    }
    let Some(account_id) = path_args.get(0).cloned() else {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "missing proxied path argument `account_id`",
        );
    };
    let mut params =
        match decode_torii_proxy_query::<routing::AccountHistoryGetParams>(query_string.as_deref())
        {
            Ok(params) => params,
            Err(response) => return response,
        };
    let limits = routing::app_query_limits();
    let page_limit = match limits.clamp_page_limit(params.limit) {
        Ok(0) => {
            return Error::AppQueryValidation {
                code: "invalid_pagination",
                message: format!(
                    "limit must be between 1 and {} for {}",
                    limits.max_page_limit,
                    routing::ENDPOINT_ACCOUNTS_HISTORY
                ),
            }
            .into_response();
        }
        Ok(limit) => limit,
        Err(error) => return error.into_response(),
    };
    params.limit = Some(page_limit);
    let count_mode_label = account_history_count_mode_label(params.count_mode.as_deref());
    let routed_by = routed_by_for_routes(app, &routes);
    if routes.len() == 1 {
        let query_string = match encode_torii_proxy_query(&params) {
            Ok(query_string) => query_string,
            Err(error) => return error.into_response(),
        };
        let mut diagnostics = ToriiFanoutDiagnostics::default();
        diagnostics.record_attempt();
        let response = execute_torii_single_route_read(
            app,
            routes[0],
            ToriiReadEndpointV1::AccountHistoryGet,
            vec![account_id],
            query_string,
            Vec::new(),
        )
        .await;
        if response.status().is_success() {
            diagnostics.record_success();
        } else {
            diagnostics.record_skipped_response(&response);
        }
        return with_torii_fanout_headers(response, diagnostics);
    }

    let (payloads, diagnostics) = match collect_torii_account_history_json_payloads(
        &routes,
        &params,
        page_limit,
        count_mode_label,
        |route, page_query_string| {
            let account_id = account_id.clone();
            async move {
                execute_torii_single_route_read(
                    app,
                    route,
                    ToriiReadEndpointV1::AccountHistoryGet,
                    vec![account_id],
                    page_query_string,
                    Vec::new(),
                )
                .await
            }
        },
    )
    .await
    {
        Ok(collected) => collected,
        Err(response) => return response,
    };

    merge_with_torii_fanout_headers(diagnostics, || {
        merged_account_history_response(
            payloads,
            params.offset,
            page_limit,
            count_mode_label,
            routed_by,
        )
    })
}

#[cfg(feature = "app_api")]
async fn collect_torii_account_history_json_payloads<F, Fut>(
    routes: &[RoutingDecision],
    params: &routing::AccountHistoryGetParams,
    page_limit: u64,
    count_mode_label: &'static str,
    mut fetch: F,
) -> Result<(Vec<Value>, ToriiFanoutDiagnostics), Response>
where
    F: FnMut(RoutingDecision, Option<String>) -> Fut,
    Fut: core::future::Future<Output = Response>,
{
    let per_route_target = (count_mode_label == "bounded")
        .then(|| params.offset.saturating_add(page_limit).saturating_add(1));
    let limits = routing::app_query_limits();
    let chunk_limit = limits.max_page_limit.max(1);
    let mut payloads = Vec::new();
    let mut diagnostics = ToriiFanoutDiagnostics::default();
    let mut last_not_found = None;
    let mut last_route_unavailable = None;

    for route in routes {
        diagnostics.record_attempt();
        let mut route_offset = 0_u64;
        let mut route_items_seen = 0_u64;
        let mut route_succeeded = false;

        loop {
            let mut page_params = params.clone();
            page_params.offset = route_offset;
            let next_limit = per_route_target
                .map(|target| {
                    target
                        .saturating_sub(route_items_seen)
                        .max(1)
                        .min(chunk_limit)
                })
                .unwrap_or(chunk_limit);
            page_params.limit = Some(next_limit);
            let page_query_string = match encode_torii_proxy_query(&page_params) {
                Ok(query_string) => query_string,
                Err(error) => return Err(error.into_response()),
            };
            let response = fetch(*route, page_query_string).await;

            if response.status() == StatusCode::NOT_FOUND {
                diagnostics.record_skipped_response(&response);
                if route_succeeded {
                    return Err(with_torii_fanout_headers(response, diagnostics));
                } else {
                    last_not_found = Some(response);
                }
                break;
            }
            if torii_response_has_reject_code(&response, "route_unavailable") {
                diagnostics.record_skipped_response(&response);
                if route_succeeded {
                    return Err(with_torii_fanout_headers(response, diagnostics));
                } else {
                    last_route_unavailable = Some(response);
                }
                break;
            }

            let payload = match torii_json_body_value(response).await {
                Ok(payload) => payload,
                Err(response) => {
                    diagnostics.record_skipped_response(&response);
                    return Err(with_torii_fanout_headers(response, diagnostics));
                }
            };
            let item_count = match list_items_from_payload(
                &payload,
                "expected account history JSON object with `items`",
            ) {
                Ok(items) => items.len(),
                Err(response) => {
                    diagnostics.record_skipped_response(&response);
                    return Err(with_torii_fanout_headers(response, diagnostics));
                }
            };
            let has_more = account_history_payload_has_more(&payload, item_count, next_limit);
            payloads.push(payload);
            route_succeeded = true;
            let item_count_u64 = u64::try_from(item_count).unwrap_or(u64::MAX);
            route_items_seen = route_items_seen.saturating_add(item_count_u64);

            if item_count == 0
                || !has_more
                || per_route_target.is_some_and(|target| route_items_seen >= target)
            {
                break;
            }
            route_offset = route_offset.saturating_add(item_count_u64);
        }

        if route_succeeded {
            diagnostics.record_success();
        }
    }

    if payloads.is_empty() {
        let response = last_not_found.unwrap_or_else(|| {
            last_route_unavailable.unwrap_or_else(|| {
                torii_proxy_error_response(
                    StatusCode::NOT_FOUND,
                    "not_found",
                    "no dataspace returned a matching result",
                )
            })
        });
        return Err(with_torii_fanout_headers(response, diagnostics));
    }

    Ok((payloads, diagnostics))
}

#[cfg(feature = "app_api")]
async fn execute_torii_read_fanout_for_resolved_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    merge: ToriiReadFanoutMergeV1,
    endpoint: ToriiReadEndpointV1,
    path_args: Vec<String>,
    query_string: Option<String>,
    body: Vec<u8>,
    response_format: ToriiProxyResponseFormatV1,
) -> Response {
    match merge {
        ToriiReadFanoutMergeV1::List => {
            match execute_torii_fanout_json_payloads_resolved_routes(
                app,
                routes,
                endpoint,
                path_args,
                query_string,
                body,
            )
            .await
            {
                Ok((_routes, payloads, diagnostics, routed_by)) => {
                    merge_with_torii_fanout_headers(diagnostics, || {
                        merged_list_response(payloads, routed_by)
                    })
                }
                Err(response) => response,
            }
        }
        ToriiReadFanoutMergeV1::Singleton => {
            if routes.is_empty() {
                return with_torii_fanout_headers(
                    torii_proxy_error_response(
                        StatusCode::SERVICE_UNAVAILABLE,
                        "route_unavailable",
                        "no Nexus dataspace routes are configured",
                    ),
                    ToriiFanoutDiagnostics::default(),
                );
            }
            let collected = match collect_torii_singleton_json_payloads(&routes, |route| {
                execute_torii_read_for_route(
                    app,
                    route,
                    torii_read_request(
                        endpoint,
                        route,
                        path_args.clone(),
                        query_string.clone(),
                        body.clone(),
                    ),
                )
            })
            .await
            {
                Ok(payloads) => payloads,
                Err(response) => return response,
            };
            merge_with_torii_fanout_headers(collected.diagnostics, || {
                if matches!(endpoint, ToriiReadEndpointV1::PipelineTransactionStatusGet) {
                    merged_pipeline_status_response(
                        collected.payloads,
                        routed_by_for_routes(app, &routes),
                    )
                } else {
                    merged_singleton_response(
                        collected.payloads,
                        routed_by_for_routes(app, &routes),
                    )
                }
            })
        }
        ToriiReadFanoutMergeV1::Account => {
            let Some(canonical_account_id) = path_args.get(0).cloned() else {
                return torii_proxy_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_proxy_request",
                    "missing proxied path argument `account_id`",
                );
            };
            execute_torii_account_read_for_resolved_routes(
                app,
                routes,
                canonical_account_id,
                response_format_from_torii_proxy(response_format),
            )
            .await
        }
        ToriiReadFanoutMergeV1::AccountHistory => {
            execute_torii_account_history_read_for_resolved_routes(
                app,
                routes,
                path_args,
                query_string,
            )
            .await
        }
        ToriiReadFanoutMergeV1::Portfolio => {
            match execute_torii_fanout_json_payloads_resolved_routes(
                app,
                routes,
                endpoint,
                path_args,
                query_string,
                body,
            )
            .await
            {
                Ok((_routes, payloads, diagnostics, routed_by)) => {
                    merge_with_torii_fanout_headers(diagnostics, || {
                        merged_portfolio_response(payloads, routed_by)
                    })
                }
                Err(response) => response,
            }
        }
        ToriiReadFanoutMergeV1::DataspaceSummary => {
            match execute_torii_fanout_json_payloads_resolved_routes(
                app,
                routes,
                endpoint,
                path_args,
                query_string,
                body,
            )
            .await
            {
                Ok((_routes, payloads, diagnostics, routed_by)) => {
                    merge_with_torii_fanout_headers(diagnostics, || {
                        merged_dataspace_summary_response(payloads, routed_by)
                    })
                }
                Err(response) => response,
            }
        }
        ToriiReadFanoutMergeV1::SpaceDirectoryBindings => {
            match execute_torii_fanout_json_payloads_resolved_routes(
                app,
                routes,
                endpoint,
                path_args,
                query_string,
                body,
            )
            .await
            {
                Ok((_routes, payloads, diagnostics, routed_by)) => {
                    merge_with_torii_fanout_headers(diagnostics, || {
                        merged_space_directory_bindings_response(payloads, routed_by)
                    })
                }
                Err(response) => response,
            }
        }
        ToriiReadFanoutMergeV1::SpaceDirectoryManifests {
            page_offset,
            page_limit,
        } => {
            match execute_torii_fanout_json_payloads_resolved_routes(
                app,
                routes,
                endpoint,
                path_args,
                query_string,
                body,
            )
            .await
            {
                Ok((_routes, payloads, diagnostics, routed_by)) => {
                    merge_with_torii_fanout_headers(diagnostics, || {
                        merged_space_directory_manifests_response(
                            payloads,
                            page_offset,
                            page_limit,
                            routed_by,
                        )
                    })
                }
                Err(response) => response,
            }
        }
    }
}

#[cfg(feature = "app_api")]
async fn execute_torii_read_fanout_proxy_request(
    app: &SharedAppState,
    request: ToriiReadFanoutProxyRequestV1,
) -> Response {
    let routes = match torii_fanout_scope_routes(app.as_ref(), &request.route_scope) {
        Ok(routes) => routes,
        Err(response) => return response,
    };
    execute_torii_read_fanout_for_resolved_routes(
        app,
        routes,
        request.merge,
        request.endpoint,
        request.path_args,
        request.query_string,
        request.body,
        request.response_format,
    )
    .await
}

#[cfg(feature = "app_api")]
async fn execute_torii_read_fanout_via_nexus(
    app: &SharedAppState,
    route_scope: ToriiFanoutRouteScopeV1,
    merge: ToriiReadFanoutMergeV1,
    endpoint: ToriiReadEndpointV1,
    path_args: Vec<String>,
    query_string: Option<String>,
    body: Vec<u8>,
    response_format: ToriiProxyResponseFormatV1,
) -> Response {
    let routes = match torii_fanout_scope_routes(app.as_ref(), &route_scope) {
        Ok(routes) => routes,
        Err(response) => return response,
    };
    if routes.len() <= 1 {
        return execute_torii_read_fanout_for_resolved_routes(
            app,
            routes,
            merge,
            endpoint,
            path_args,
            query_string,
            body,
            response_format,
        )
        .await;
    }

    let request = torii_read_fanout_request(
        endpoint,
        route_scope,
        merge,
        path_args,
        query_string,
        body,
        response_format,
    );
    let nexus_route = match torii_nexus_route(app.as_ref()) {
        Ok(route) => route,
        Err(response) => return response,
    };
    if local_read_fanout_coordinator_enabled()
        || should_execute_route_locally(app.as_ref(), nexus_route)
    {
        return execute_torii_read_fanout_proxy_request(app, request).await;
    }

    execute_torii_proxy_request_with_fallback(
        app,
        nexus_route,
        ToriiProxyRequestKindV1::ReadFanout(request),
    )
    .await
}

