async fn handler_pipeline_recovery_fastpq_proofs(
    State(app): State<SharedAppState>,
    AxPath(height): AxPath<u64>,
) -> Result<impl IntoResponse, Error> {
    let Some(sidecar) = app.kura.read_pipeline_metadata(height) else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };

    let mut root = norito::json::Map::new();
    root.insert(
        "height".to_string(),
        norito::json::to_value(&sidecar.height).expect("serialize pipeline height"),
    );
    root.insert(
        "block_hash".to_string(),
        norito::json::to_value(&sidecar.block_hash.to_string())
            .expect("serialize pipeline block hash"),
    );
    root.insert(
        "proofs".to_string(),
        norito::json::Value::Array(
            sidecar
                .fastpq_proofs
                .iter()
                .map(|snapshot| fastpq_proof_snapshot_recovery_json(&app.kura, height, snapshot))
                .collect(),
        ),
    );
    match norito::json::to_json_pretty(&norito::json::Value::Object(root)) {
        Ok(serialized) => {
            let body = axum::body::Body::from(serialized);
            Ok(axum::http::Response::builder()
                .status(axum::http::StatusCode::OK)
                .header(axum::http::header::CONTENT_TYPE, "application/json")
                .body(body)
                .unwrap())
        }
        Err(err) => Err(Error::SerializationFailure {
            context: "pipeline_recovery_fastpq_proofs",
            source: Box::new(err),
        }),
    }
}

fn fastpq_proof_snapshot_recovery_json(
    kura: &Kura,
    height: u64,
    snapshot: &iroha_core::kura::FastpqProofSnapshot,
) -> norito::json::Value {
    let mut entry = snapshot.to_json_value();
    let norito::json::Value::Object(ref mut object) = entry else {
        return entry;
    };

    match fastpq_committed_batch_base64(kura, height, snapshot) {
        Some((batch, reconstructed)) => {
            object.insert(
                "batch".to_string(),
                norito::json::to_value(&batch).expect("serialize FASTPQ batch"),
            );
            object.insert(
                "batch_compact".to_string(),
                norito::json::to_value(&false).expect("serialize FASTPQ batch compact flag"),
            );
            object.insert(
                "batch_reconstructed_from_block".to_string(),
                norito::json::to_value(&reconstructed)
                    .expect("serialize FASTPQ batch reconstruction flag"),
            );
        }
        None => {
            object.insert(
                "batch_compact".to_string(),
                norito::json::to_value(&snapshot.batch.transitions.is_empty())
                    .expect("serialize FASTPQ batch compact flag"),
            );
            if snapshot.transition_count > 0 && snapshot.batch.transitions.is_empty() {
                object.insert(
                    "batch_reconstruction_error".to_string(),
                    norito::json::to_value(
                        "committed block transcripts were not available for this FASTPQ proof",
                    )
                    .expect("serialize FASTPQ batch reconstruction error"),
                );
            }
        }
    }

    entry
}

fn fastpq_committed_batch_base64(
    kura: &Kura,
    height: u64,
    snapshot: &iroha_core::kura::FastpqProofSnapshot,
) -> Option<(String, bool)> {
    if snapshot.transition_count == 0 {
        return None;
    }
    if !snapshot.batch.transitions.is_empty() {
        let batch = base64::engine::general_purpose::STANDARD
            .encode(norito::to_bytes(&snapshot.batch).expect("encode FASTPQ recovery batch"));
        return Some((batch, false));
    }

    let Some(height) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
        iroha_logger::warn!(
            height,
            "cannot reconstruct FASTPQ batch for invalid block height"
        );
        return None;
    };
    let Some(block) = kura.get_block(height) else {
        iroha_logger::warn!(
            height = height.get(),
            entry_hash = %snapshot.entry_hash,
            "cannot reconstruct FASTPQ batch because committed block is unavailable"
        );
        return None;
    };
    let Some(transcripts) = block.fastpq_transcripts().get(&snapshot.entry_hash) else {
        iroha_logger::warn!(
            height = height.get(),
            entry_hash = %snapshot.entry_hash,
            "cannot reconstruct FASTPQ batch because committed block has no matching transcript"
        );
        return None;
    };
    match iroha_core::fastpq::batch_from_transcript_bundle(
        snapshot.parameter.clone(),
        snapshot.batch.public_inputs,
        snapshot.entry_hash,
        transcripts,
    ) {
        Ok(batch) => Some((
            base64::engine::general_purpose::STANDARD
                .encode(norito::to_bytes(&batch).expect("encode reconstructed FASTPQ batch")),
            true,
        )),
        Err(err) => {
            iroha_logger::warn!(
                height = height.get(),
                entry_hash = %snapshot.entry_hash,
                ?err,
                "failed to reconstruct FASTPQ batch from committed transcripts"
            );
            None
        }
    }
}

#[derive(JsonDeserialize, crate::json_macros::JsonSerialize, Clone, Debug)]
struct PipelineStatusQuery {
    #[norito(default)]
    hash: Option<String>,
    #[norito(default)]
    scope: Option<String>,
}

#[derive(JsonDeserialize, crate::json_macros::JsonSerialize, Clone, Debug)]
struct TriggerCompletionQuery {
    #[norito(default)]
    id: Option<String>,
    #[norito(default)]
    entrypoint_hash: Option<String>,
    #[norito(default)]
    outcome: Option<String>,
    #[norito(default)]
    from_height: Option<u64>,
    #[norito(default)]
    to_height: Option<u64>,
    #[norito(default)]
    limit: Option<u64>,
    #[norito(default)]
    scan_limit_blocks: Option<u64>,
    #[norito(default)]
    include_reconstructed: Option<bool>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TriggerCompletionOutcomeFilter {
    All,
    Success,
    Failure,
}

impl TriggerCompletionOutcomeFilter {
    fn parse(raw: Option<&str>) -> Result<Self, Error> {
        let normalized = raw
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("all")
            .to_ascii_lowercase();
        match normalized.as_str() {
            "all" | "*" => Ok(Self::All),
            "success" | "ok" => Ok(Self::Success),
            "failure" | "failed" | "error" => Ok(Self::Failure),
            _ => Err(conversion_error(format!(
                "invalid outcome query parameter \"{normalized}\" (expected all|success|failure)"
            ))),
        }
    }

    fn matches(self, outcome: &str) -> bool {
        match self {
            Self::All => true,
            Self::Success => matches!(outcome, "Success"),
            Self::Failure => matches!(outcome, "Failure"),
        }
    }
}

const TRIGGER_COMPLETION_DEFAULT_LIMIT: u64 = 100;
const TRIGGER_COMPLETION_MAX_LIMIT: u64 = 1_000;
const TRIGGER_COMPLETION_DEFAULT_SCAN_BLOCKS: u64 = 1_000;
const TRIGGER_COMPLETION_MAX_SCAN_BLOCKS: u64 = 10_000;

fn trigger_completion_outcome(outcome: &TriggerCompletedOutcome) -> (&'static str, Option<String>) {
    match outcome {
        TriggerCompletedOutcome::Success => ("Success", None),
        TriggerCompletedOutcome::Failure(message) => ("Failure", Some(message.clone())),
    }
}

fn trigger_completion_summary_from_event(
    event: &TriggerCompletedEvent,
) -> TriggerCompletionSummary {
    let (outcome, message) = trigger_completion_outcome(event.outcome());
    TriggerCompletionSummary {
        trigger_id: event.trigger_id().to_string(),
        trigger_execution_hash: event.trigger_execution_hash().to_string(),
        step_index: *event.step_index(),
        outcome: outcome.to_owned(),
        message,
    }
}

fn trigger_completion_record_from_event(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
    event: &TriggerCompletedEvent,
    source: &str,
) -> TriggerCompletionRecord {
    let entrypoint_index = block
        .entrypoint_hashes()
        .position(|hash| hash == *event.trigger_execution_hash())
        .and_then(|index| u64::try_from(index).ok());
    TriggerCompletionRecord {
        block_height,
        entrypoint_index,
        completion: trigger_completion_summary_from_event(event),
        source: source.to_owned(),
    }
}

fn trigger_completion_record_from_parts(
    block_height: u64,
    entrypoint_index: usize,
    trigger_id: String,
    trigger_execution_hash: String,
    step_index: u32,
    outcome: &str,
    message: Option<String>,
    source: &str,
) -> TriggerCompletionRecord {
    TriggerCompletionRecord {
        block_height,
        entrypoint_index: u64::try_from(entrypoint_index).ok(),
        completion: TriggerCompletionSummary {
            trigger_id,
            trigger_execution_hash,
            step_index,
            outcome: outcome.to_owned(),
            message,
        },
        source: source.to_owned(),
    }
}

fn reconstruct_trigger_completion_records(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
) -> Vec<TriggerCompletionRecord> {
    let mut records = Vec::new();
    for (entrypoint_index, entrypoint, result) in block.entrypoint_results() {
        let execution_hash = entrypoint.hash().to_string();
        if let TransactionEntrypoint::Time(time_entrypoint) = &entrypoint {
            match &result.0 {
                Ok(_) => records.push(trigger_completion_record_from_parts(
                    block_height,
                    entrypoint_index,
                    time_entrypoint.id.to_string(),
                    execution_hash.clone(),
                    0,
                    "Success",
                    None,
                    "reconstructed_result",
                )),
                Err(reason) => records.push(trigger_completion_record_from_parts(
                    block_height,
                    entrypoint_index,
                    time_entrypoint.id.to_string(),
                    execution_hash.clone(),
                    0,
                    "Failure",
                    Some(reason.to_string()),
                    "reconstructed_result",
                )),
            }
        }

        let Ok(sequence) = &result.0 else {
            continue;
        };
        let first_data_step = if matches!(entrypoint, TransactionEntrypoint::Time(_)) {
            1_u32
        } else {
            0_u32
        };
        for (offset, step) in sequence.iter().enumerate() {
            let step_index =
                first_data_step.saturating_add(u32::try_from(offset).unwrap_or(u32::MAX));
            records.push(trigger_completion_record_from_parts(
                block_height,
                entrypoint_index,
                step.id.to_string(),
                execution_hash.clone(),
                step_index,
                "Success",
                None,
                "reconstructed_result",
            ));
        }
    }
    records
}

fn trigger_completion_record_matches(
    record: &TriggerCompletionRecord,
    trigger_id: Option<&str>,
    entrypoint_hash: Option<&str>,
    outcome: TriggerCompletionOutcomeFilter,
) -> bool {
    if let Some(trigger_id) = trigger_id
        && record.completion.trigger_id != trigger_id
    {
        return false;
    }
    if let Some(entrypoint_hash) = entrypoint_hash
        && record.completion.trigger_execution_hash != entrypoint_hash
    {
        return false;
    }
    outcome.matches(&record.completion.outcome)
}

fn trigger_completion_records_for_block(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
    include_reconstructed: bool,
    entrypoint_hash: Option<&str>,
) -> Vec<TriggerCompletionRecord> {
    let persisted = block
        .trigger_completions()
        .unwrap_or_default()
        .iter()
        .map(|event| {
            trigger_completion_record_from_event(block, block_height, event, "block_result")
        })
        .collect::<Vec<_>>();
    if !include_reconstructed {
        return persisted;
    }
    if persisted.is_empty() {
        return reconstruct_trigger_completion_records(block, block_height);
    }
    if let Some(entrypoint_hash) = entrypoint_hash
        && !persisted
            .iter()
            .any(|record| record.completion.trigger_execution_hash == entrypoint_hash)
    {
        return reconstruct_trigger_completion_records(block, block_height);
    }
    persisted
}

fn trigger_completion_from_height(query: &TriggerCompletionQuery, requested_to: u64) -> u64 {
    query.from_height.map_or_else(
        || {
            let scan_limit = query
                .scan_limit_blocks
                .unwrap_or(TRIGGER_COMPLETION_DEFAULT_SCAN_BLOCKS)
                .clamp(1, TRIGGER_COMPLETION_MAX_SCAN_BLOCKS);
            requested_to
                .saturating_sub(scan_limit.saturating_sub(1))
                .max(1)
        },
        |from_height| from_height.max(1),
    )
}

fn trigger_completion_query_response(
    app: &SharedAppState,
    query: &TriggerCompletionQuery,
) -> Result<TriggerCompletionListResponse, Error> {
    let latest_height = u64::try_from(app.state.committed_height()).unwrap_or(u64::MAX);
    let limit = query
        .limit
        .unwrap_or(TRIGGER_COMPLETION_DEFAULT_LIMIT)
        .clamp(1, TRIGGER_COMPLETION_MAX_LIMIT);
    let include_reconstructed = query.include_reconstructed.unwrap_or(true);
    let outcome = TriggerCompletionOutcomeFilter::parse(query.outcome.as_deref())?;
    let requested_to = query.to_height.unwrap_or(latest_height).min(latest_height);

    if latest_height == 0 || requested_to == 0 {
        return Ok(TriggerCompletionListResponse {
            latest_height,
            from_height: 0,
            to_height: requested_to,
            scanned_blocks: 0,
            limit,
            completions: Vec::new(),
        });
    }

    let from_height = trigger_completion_from_height(query, requested_to);
    if from_height > requested_to {
        return Ok(TriggerCompletionListResponse {
            latest_height,
            from_height,
            to_height: requested_to,
            scanned_blocks: 0,
            limit,
            completions: Vec::new(),
        });
    }

    let mut completions = Vec::new();
    let mut scanned_blocks = 0_u64;
    for height in (from_height..=requested_to).rev() {
        scanned_blocks = scanned_blocks.saturating_add(1);
        let Some(height_usize) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
            continue;
        };
        let Some(block) = app.kura.get_block(height_usize) else {
            continue;
        };
        for record in trigger_completion_records_for_block(
            block.as_ref(),
            height,
            include_reconstructed,
            query.entrypoint_hash.as_deref(),
        ) {
            if !trigger_completion_record_matches(
                &record,
                query.id.as_deref(),
                query.entrypoint_hash.as_deref(),
                outcome,
            ) {
                continue;
            }
            completions.push(record);
            if u64::try_from(completions.len()).unwrap_or(u64::MAX) >= limit {
                return Ok(TriggerCompletionListResponse {
                    latest_height,
                    from_height,
                    to_height: requested_to,
                    scanned_blocks,
                    limit,
                    completions,
                });
            }
        }
    }

    Ok(TriggerCompletionListResponse {
        latest_height,
        from_height,
        to_height: requested_to,
        scanned_blocks,
        limit,
        completions,
    })
}

fn trigger_completion_summaries_for_entrypoint_hash(
    app: &SharedAppState,
    block_height: u64,
    entrypoint_hash: &str,
) -> Vec<TriggerCompletionSummary> {
    let query = TriggerCompletionQuery {
        id: None,
        entrypoint_hash: Some(entrypoint_hash.to_owned()),
        outcome: None,
        from_height: Some(block_height),
        to_height: Some(block_height),
        limit: Some(TRIGGER_COMPLETION_MAX_LIMIT),
        scan_limit_blocks: Some(1),
        include_reconstructed: Some(true),
    };
    trigger_completion_query_response(app, &query)
        .map(|response| {
            response
                .completions
                .into_iter()
                .map(|record| record.completion)
                .collect()
        })
        .unwrap_or_default()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PipelineStatusReadScope {
    Local,
    Global,
}

impl PipelineStatusReadScope {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Local => "local",
            Self::Global => "global",
        }
    }
}

fn parse_pipeline_status_scope(raw: Option<&str>) -> Result<PipelineStatusReadScope, Error> {
    let normalized = raw
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("global")
        .to_ascii_lowercase();
    match normalized.as_str() {
        "local" => Ok(PipelineStatusReadScope::Local),
        "global" | "auto" => Ok(PipelineStatusReadScope::Global),
        _ => Err(conversion_error(format!(
            "invalid scope query parameter \"{normalized}\" (expected local|global|auto)"
        ))),
    }
}

fn parse_signed_transaction_hash(raw: &str) -> Result<HashOf<SignedTransaction>, Error> {
    raw.trim()
        .parse::<HashOf<SignedTransaction>>()
        .map_err(|_| conversion_error("invalid signed transaction hash".to_owned()))
}

fn pipeline_status_response(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
    entry: &PipelineStatusEntry,
    scope: PipelineStatusReadScope,
    resolved_from: &'static str,
) -> PipelineTransactionStatusResponse {
    let mut response = PipelineTransactionStatusResponse::new(
        hash.to_string(),
        PipelineTransactionStatus {
            kind: entry.kind.as_str().to_owned(),
            block_height: entry.block_height.map(NonZeroU64::get),
            rejection_reason: entry.rejection.clone(),
        },
        scope.as_str().to_owned(),
        resolved_from.to_owned(),
    );
    if let Some(block_height) = entry.block_height.map(NonZeroU64::get) {
        response.trigger_completions =
            trigger_completion_summaries_for_entrypoint_hash(app, block_height, &hash.to_string());
    }
    response
}

fn pipeline_status_from_state(
    app: &AppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<PipelineStatusEntry> {
    let height = app.state.committed_transaction_height(hash)?;
    let height_u64 = u64::try_from(height.get()).ok()?;
    let height_nz = NonZeroU64::new(height_u64)?;
    let block = app.kura.get_block(height)?;
    let block_ref = block.as_ref();
    for (index, entrypoint, result) in block_ref.entrypoint_results() {
        if index >= block_ref.external_entrypoint_count() {
            break;
        }
        let entrypoint_hash =
            HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::from(entrypoint.hash()));
        if entrypoint_hash != *hash {
            continue;
        }
        let (kind, rejection) = match &result.0 {
            Ok(_) => (PipelineStatusKind::Applied, None),
            Err(reason) => (PipelineStatusKind::Rejected, Some(reason.clone())),
        };
        return Some(PipelineStatusEntry::fresh(kind, Some(height_nz), rejection));
    }
    None
}

fn pipeline_status_terminal_or_state_entry(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<(PipelineStatusEntry, &'static str)> {
    app.pipeline_status_cache.refresh_pending_blocks(&app.kura);

    if let Some(entry) = pipeline_status_from_state(app.as_ref(), hash) {
        app.pipeline_status_cache
            .record_entry(hash.clone(), entry.clone());
        return Some((entry, "state"));
    }

    if let Some(entry) = app.pipeline_status_cache.lookup(hash) {
        if entry.kind.is_terminal() {
            return Some((entry, "cache"));
        }
    }

    None
}

fn pipeline_status_local_entry(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<(PipelineStatusEntry, &'static str)> {
    if let Some(entry) = pipeline_status_terminal_or_state_entry(app, hash) {
        return Some(entry);
    }

    if let Some(entry) = app.pipeline_status_cache.lookup(hash) {
        if entry.kind == PipelineStatusKind::Queued
            && !app.queue.contains_pending_hash(hash.clone(), &app.state)
        {
            app.pipeline_status_cache.remove_entry_by_hash(hash);
            return None;
        }
        return Some((entry, "cache"));
    }

    if app.queue.contains_pending_hash(hash.clone(), &app.state) {
        let entry = PipelineStatusEntry::fresh(PipelineStatusKind::Queued, None, None);
        app.pipeline_status_cache
            .record_entry(hash.clone(), entry.clone());
        return Some((entry, "queue"));
    }

    None
}

fn pipeline_status_response_with_route(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
    entry: &PipelineStatusEntry,
    scope: PipelineStatusReadScope,
    resolved_from: &'static str,
    format: ResponseFormat,
    route: Option<(RoutingDecision, &'static str)>,
) -> Response {
    let mut response = crate::utils::respond_with_format(
        pipeline_status_response(app, hash, entry, scope, resolved_from),
        format,
    );
    if let Some((routing_decision, routed_by)) = route {
        insert_routing_headers(&mut response, routing_decision, routed_by);
    }
    response
}

fn pipeline_status_not_found_error() -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::NotFound,
    ))
}

fn pipeline_status_proxy_query(
    hash: &HashOf<SignedTransaction>,
    scope: PipelineStatusReadScope,
) -> Result<Option<String>, Error> {
    encode_torii_proxy_query(&PipelineStatusQuery {
        hash: Some(hash.to_string()),
        scope: Some(scope.as_str().to_owned()),
    })
}

fn execute_pipeline_status_local_read(
    app: &SharedAppState,
    query: &PipelineStatusQuery,
    format: ResponseFormat,
    route: Option<(RoutingDecision, &'static str)>,
) -> Result<Response, Error> {
    let hash_raw = query
        .hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| conversion_error("missing hash query parameter".to_owned()))?;
    let read_scope = parse_pipeline_status_scope(query.scope.as_deref())?;
    let hash = parse_signed_transaction_hash(hash_raw)?;

    let local_entry = if matches!(read_scope, PipelineStatusReadScope::Local) {
        pipeline_status_local_entry(app, &hash)
    } else {
        pipeline_status_terminal_or_state_entry(app, &hash)
    };

    if let Some((entry, resolved_from)) = local_entry {
        return Ok(pipeline_status_response_with_route(
            app,
            &hash,
            &entry,
            read_scope,
            resolved_from,
            format,
            route,
        ));
    }

    Err(pipeline_status_not_found_error())
}

#[cfg(feature = "app_api")]
fn pipeline_status_payload_is_authoritative_hint(
    payload: &PipelineTransactionStatusResponse,
) -> bool {
    match payload.status.kind.as_str() {
        "Applied" => true,
        "Rejected" | "Expired" => payload.resolved_from == "state",
        _ => false,
    }
}

#[cfg(feature = "app_api")]
async fn pipeline_status_hinted_global_response(
    response: Response,
) -> Result<Option<Response>, Response> {
    if should_skip_singleton_routed_query_route_error(&response) {
        return Ok(None);
    }
    if !response.status().is_success() {
        return Ok(Some(response));
    }

    let (parts, body) = response.into_parts();
    let bytes = axum::body::to_bytes(body, usize::MAX)
        .await
        .map_err(|error| {
            torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "invalid_proxy_response",
                format!("failed to read hinted pipeline status response: {error}"),
            )
        })?;
    let is_terminal = norito::json::from_slice::<PipelineTransactionStatusResponse>(&bytes)
        .map(|payload| pipeline_status_payload_is_authoritative_hint(&payload))
        .unwrap_or(false);
    let response = Response::from_parts(parts, Body::from(bytes));

    Ok(is_terminal.then_some(response))
}

async fn handler_pipeline_transaction_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    AxQuery(query): AxQuery<PipelineStatusQuery>,
) -> Result<Response, Error> {
    let remote_ip = remote.ip();
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(format) => format,
        Err(resp) => return Ok(resp),
    };
    let read_scope = parse_pipeline_status_scope(query.scope.as_deref())?;
    let hash_raw = query
        .hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| conversion_error("missing hash query parameter".to_owned()))?;
    let hash = parse_signed_transaction_hash(hash_raw)?;

    if let Ok(response) = execute_pipeline_status_local_read(&app, &query, format, None) {
        return Ok(response);
    }

    if matches!(read_scope, PipelineStatusReadScope::Local) {
        return Err(pipeline_status_not_found_error());
    }

    #[cfg(feature = "app_api")]
    {
        check_access_with_rate_limiter(
            &app,
            &headers,
            Some(remote_ip),
            "v1/pipeline/transactions/status",
            &app.pipeline_status_rate_limiter,
        )
        .await?;

        let query_string = pipeline_status_proxy_query(&hash, read_scope)?;
        if let Some(route) = queue::routing_plan_hint(&hash).map(|plan| plan.coordinator_route()) {
            let hinted = execute_torii_single_route_read(
                &app,
                route,
                ToriiReadEndpointV1::PipelineTransactionStatusGet,
                Vec::new(),
                query_string.clone(),
                Vec::new(),
            )
            .await;
            match pipeline_status_hinted_global_response(hinted).await {
                Ok(Some(hinted)) => return Ok(hinted),
                Ok(None) => {}
                Err(response) => return Ok(response),
            }
        }

        Ok(execute_torii_fanout_singleton_read(
            &app,
            ToriiReadEndpointV1::PipelineTransactionStatusGet,
            Vec::new(),
            query_string,
            Vec::new(),
        )
        .await)
    }

    #[cfg(not(feature = "app_api"))]
    {
        let _ = headers;
        let _ = remote_ip;
        let _ = hash;
        Err(pipeline_status_not_found_error())
    }
}

async fn handler_trigger_completions(
    State(app): State<SharedAppState>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    AxQuery(query): AxQuery<TriggerCompletionQuery>,
) -> Result<Response, Error> {
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(format) => format,
        Err(resp) => return Ok(resp),
    };
    Ok(crate::utils::respond_with_format(
        trigger_completion_query_response(&app, &query)?,
        format,
    ))
}

async fn handler_policy(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
) -> Result<impl IntoResponse, Error> {
    #[allow(clippy::too_many_arguments, clippy::ref_option)]
    fn build_policy_body(
        require_token: bool,
        fee_policy: &FeePolicy,
        queue_len: u64,
        normal_th: usize,
        stream_th: usize,
        sub_th: usize,
        token_required: bool,
    ) -> axum::response::Response {
        let mut obj = norito::json::Map::new();
        obj.insert(
            "require_api_token".into(),
            norito::json::Value::from(require_token),
        );
        obj.insert(
            "token_required".into(),
            norito::json::Value::from(token_required),
        );
        match fee_policy.asset_id() {
            Some(asset) => obj.insert(
                "fee_asset_id".into(),
                norito::json::Value::from(asset.to_owned()),
            ),
            None => obj.insert("fee_asset_id".into(), norito::json::Value::Null),
        };
        match fee_policy.receiver() {
            Some(r) => obj.insert(
                "fee_receiver".into(),
                norito::json::Value::from(r.to_owned()),
            ),
            None => obj.insert("fee_receiver".into(), norito::json::Value::Null),
        };
        match fee_policy.amount() {
            Some(amount) => obj.insert("fee_amount".into(), norito::json::Value::from(amount)),
            None => obj.insert("fee_amount".into(), norito::json::Value::Null),
        };
        obj.insert("queue_len".into(), norito::json::Value::from(queue_len));
        obj.insert(
            "rate_limit_threshold".into(),
            norito::json::Value::from(normal_th as u64),
        );
        obj.insert(
            "stream_rate_limit_threshold".into(),
            norito::json::Value::from(stream_th as u64),
        );
        obj.insert(
            "subscription_rate_limit_threshold".into(),
            norito::json::Value::from(sub_th as u64),
        );
        let fees_enabled = fee_policy.is_enabled();
        let enforced = true;
        let stream_enforced = fees_enabled || (queue_len as usize) >= stream_th;
        let sub_enforced = fees_enabled || (queue_len as usize) >= sub_th;
        obj.insert(
            "rate_limit_enforced".into(),
            norito::json::Value::from(enforced),
        );
        obj.insert(
            "stream_rate_limit_enforced".into(),
            norito::json::Value::from(stream_enforced),
        );
        obj.insert(
            "subscription_rate_limit_enforced".into(),
            norito::json::Value::from(sub_enforced),
        );
        let explain = format!(
            "tx_rate_limit_always_on=true, fees_enabled={}, queue_len={}, thresholds(normal={}, stream={}, subscription={})",
            fees_enabled, queue_len, normal_th, stream_th, sub_th
        );
        obj.insert("explain".into(), norito::json::Value::from(explain));
        let body = norito::json::to_json_pretty(&norito::json::Value::Object(obj))
            .unwrap_or_else(|_| "{}".into());
        let mut resp = axum::response::Response::new(axum::body::Body::from(body));
        resp.headers_mut().insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/json"),
        );
        resp
    }

    let queue_len = app.queue.active_len() as u64;
    let token_required = app.require_api_token && !app.api_tokens_set.is_empty();

    if limits::is_allowed_by_cidr(&headers, Some(remote.ip()), &app.allow_nets) {
        return Ok(build_policy_body(
            app.require_api_token,
            &app.fee_policy,
            queue_len,
            app.high_load_tx_threshold,
            app.high_load_stream_tx_threshold,
            app.high_load_subscription_tx_threshold,
            token_required,
        ));
    }

    let token_hdr = headers
        .get("x-api-token")
        .and_then(|v| v.to_str().ok())
        .map(ToString::to_string);
    if app.require_api_token && !app.api_tokens_set.is_empty() {
        let ok = token_hdr
            .as_ref()
            .is_some_and(|t| app.api_tokens_set.contains(t));
        if !ok {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
            )));
        }
    }
    let key = rate_limit_key(
        &headers,
        Some(remote.ip()),
        "v1/policy",
        app.api_token_enforced(),
    );
    if !app.rate_limiter.allow(&key).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }

    Ok(build_policy_body(
        app.require_api_token,
        &app.fee_policy,
        queue_len,
        app.high_load_tx_threshold,
        app.high_load_stream_tx_threshold,
        app.high_load_subscription_tx_threshold,
        token_required,
    ))
}

async fn handler_signed_query(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    crate::NoritoQuery(query_options): crate::NoritoQuery<QueryOptions>,
    crate::utils::extractors::JsonOrNoritoVersioned(query_request): crate::utils::extractors::JsonOrNoritoVersioned<
        iroha_data_model::query::SignedQuery,
    >,
) -> Result<Response, Error> {
    let tel = app.telemetry.clone();
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };

    if !limits::is_allowed_by_cidr(&headers, Some(remote.ip()), &app.allow_nets) {
        let token_hdr = headers
            .get("x-api-token")
            .and_then(|v| v.to_str().ok())
            .map(ToString::to_string);
        if app.require_api_token && !app.api_tokens_set.is_empty() {
            let ok = token_hdr
                .as_ref()
                .is_some_and(|t| app.api_tokens_set.contains(t));
            if !ok {
                return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
                )));
            }
        }
        let key = token_hdr.unwrap_or_else(|| "query".to_string());
        if !limits::allow_conditionally(&app.rate_limiter, &key, true).await {
            return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
            )));
        }
    }

    let query_scope = signed_query_scope_for_app(app.as_ref(), &query_request.payload);

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    let should_nexus_fanout = match &query_scope {
        SignedQueryScope::CrossDataspaceFanout
            if torii_all_dataspace_routes(app.as_ref()).len() > 1 =>
        {
            true
        }
        SignedQueryScope::TargetAccount(account_id) => {
            let routes = match torii_target_account_routes(app.as_ref(), account_id) {
                Ok(routes) => routes,
                Err(response) => return Ok(response),
            };
            routes.len() > 1
        }
        SignedQueryScope::TargetAlias(alias) => {
            let routes = match torii_target_alias_routes(app.as_ref(), alias) {
                Ok(routes) => routes,
                Err(response) => return Ok(response),
            };
            routes.len() > 1
        }
        SignedQueryScope::TargetDomain(domain_id) => {
            let routes = match torii_target_domain_routes(app.as_ref(), domain_id) {
                Ok(routes) => routes,
                Err(response) => return Ok(response),
            };
            routes.len() > 1
        }
        _ => false,
    };

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    if should_nexus_fanout {
        let verified_query = routing::verify_signed_query_request(query_request)?;
        return Ok(execute_torii_query_via_nexus_fanout(&app, verified_query, format).await);
    }

    let routing_decision = match &query_scope {
        SignedQueryScope::LocalReplicated => None,
        SignedQueryScope::TargetAccount(account_id) => {
            match torii_target_account_routes(app.as_ref(), account_id) {
                Ok(routes) => routes.into_iter().next(),
                Err(response) => return Ok(response),
            }
        }
        SignedQueryScope::TargetAlias(alias) => {
            match torii_target_alias_routes(app.as_ref(), alias) {
                Ok(routes) => routes.into_iter().next(),
                Err(response) => return Ok(response),
            }
        }
        SignedQueryScope::TargetDomain(domain_id) => {
            match torii_target_domain_routes(app.as_ref(), domain_id) {
                Ok(routes) => routes.into_iter().next(),
                Err(response) => return Ok(response),
            }
        }
        SignedQueryScope::AuthorityRouted | SignedQueryScope::CrossDataspaceFanout => {
            match resolve_signed_query_routing(app.as_ref(), &query_request) {
                Ok(decision) => Some(decision),
                Err(error) => {
                    iroha_logger::warn!(%error, "failed to resolve signed query routing at ingress");
                    None
                }
            }
        }
    };

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    if let Some(routing_decision) = routing_decision
        && !should_execute_route_locally(app.as_ref(), routing_decision)
    {
        return Ok(
            execute_torii_query_via_proxy(&app, query_request, routing_decision, format).await,
        );
    }

    let _query_permit = acquire_query_admission(
        app.as_ref(),
        matches!(
            &query_request.payload.request,
            iroha_data_model::query::QueryRequest::Start(_)
        ),
    )
    .await?;

    let mut response = routing::handle_queries_with_opts(
        app.query_service.clone(),
        app.state.clone(),
        query_request,
        tel,
        crate::NoritoQuery(query_options),
        format,
    )
    .await?;
    if let Some(routing_decision) = routing_decision {
        insert_routing_headers(&mut response, routing_decision, "local");
    }
    Ok(response)
}

#[cfg(feature = "connect")]
fn connect_remote_ip_from_headers(headers: &axum::http::HeaderMap) -> Result<IpAddr, &'static str> {
    headers
        .get(limits::REMOTE_ADDR_HEADER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse().ok())
        .ok_or("connect: remote addr unavailable")
}

#[cfg(feature = "connect")]
async fn handle_connect_ws_logic(
    app: SharedAppState,
    headers: axum::http::HeaderMap,
    q: routing::ConnectWsQuery,
    ws: WebSocketUpgrade,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
) -> axum::response::Response {
    let bus = app.connect_bus.clone();
    let remote_ip = match connect_remote_ip_from_headers(&headers) {
        Ok(ip) => ip,
        Err(message) => return (StatusCode::BAD_REQUEST, message).into_response(),
    };
    let mut permit = match bus.pre_ws_handshake(remote_ip).await {
        Ok(permit) => permit,
        Err((code, msg)) => return (code, msg).into_response(),
    };
    let sid = match crate::connect::decode_sid(&q.sid) {
        Ok(sid) => sid,
        Err(_) => {
            permit.release().await;
            return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response();
        }
    };
    let role = match q.role.as_str() {
        "app" => iroha_torii_shared::connect::Role::App,
        "wallet" => iroha_torii_shared::connect::Role::Wallet,
        other => {
            permit.release().await;
            return (
                StatusCode::BAD_REQUEST,
                format!("connect: bad role {other}"),
            )
                .into_response();
        }
    };
    let token = match resolve_connect_ws_token(&headers) {
        Ok(token) => token,
        Err(response) => {
            permit.release().await;
            return response;
        }
    };
    if let Err((code, msg)) = bus.authorize_token(sid, role, &token.token).await {
        permit.release().await;
        return (code, msg).into_response();
    }
    let ws = if let Some(protocol) = token.protocol {
        ws.protocols([protocol])
    } else {
        ws
    };
    let preauth_guard = take_preauth_upgrade_guard(preauth_guard);
    ws.on_upgrade(move |ws| async move {
        let _preauth_guard = preauth_guard;
        let result = connect::handle_ws(bus, q, ws).await;
        permit.release().await;
        if let Err(e) = result {
            iroha_logger::warn!(%e, "connect ws session ended with error");
        }
    })
}

#[cfg(feature = "connect")]
#[allow(dead_code)]
fn _assert_websocket_send() {
    fn assert_send<T: Send>() {}
    fn assert_sync<T: Sync>() {}
    assert_send::<WebSocketUpgrade>();
    assert_sync::<WebSocketUpgrade>();
}

#[cfg(feature = "connect")]
fn require_connect_enabled(app: &SharedAppState) -> Result<(), Error> {
    if app.connect_enabled {
        Ok(())
    } else {
        Err(Error::AppServiceUnavailable {
            code: "connect_disabled",
            message: "Iroha Connect is disabled by node configuration".to_owned(),
        })
    }
}

#[cfg(feature = "connect")]
async fn handler_connect_ws(
    State(app): State<SharedAppState>,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    ws: WebSocketUpgrade,
) -> axum::response::Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let query = match parse_connect_ws_query(raw_query.as_deref()) {
        Ok(q) => q,
        Err(response) => return response,
    };
    handle_connect_ws_logic(app, headers, query, ws, preauth_guard).await
}

#[cfg(feature = "connect")]
async fn handler_connect_session(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    NoritoJson(req): NoritoJson<routing::ConnectSessionRequest>,
) -> Result<JsonBody<routing::ConnectSessionResponse>> {
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};

    require_connect_enabled(&app)?;

    let remote_ip = connect_remote_ip_from_headers(&headers).map_err(|message| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(message.to_owned()),
        ))
    })?;
    app.connect_bus
        .pre_session_create(remote_ip)
        .await
        .map_err(|(code, msg)| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "connect session rejected ({code}): {msg}"
                )),
            ))
        })?;

    let missing_sid = req.sid.is_none();
    let chain_id = app.chain_id.clone();
    let JsonBody(response) = routing::handle_connect_session(chain_id, NoritoJson(req)).await?;
    assert!(!missing_sid, "connect session handler missing sid");

    let malformed = |msg: String| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(msg),
        ))
    };

    let sid_bytes = B64
        .decode(response.sid.as_bytes())
        .map_err(|err| malformed(format!("connect session sid decode failed: {err}")))?;
    let sid: crate::connect::Sid = sid_bytes
        .try_into()
        .map_err(|_| malformed("connect session sid had wrong length".into()))?;

    app.connect_bus
        .clone()
        .register_tokens(
            sid,
            response.token_app.clone(),
            response.token_wallet.clone(),
            response.token_management.clone(),
            response.token_relay.clone(),
        )
        .await
        .map_err(|err| match err {
            crate::connect::RegisterSessionError::Exists => {
                malformed("connect session already exists for provided sid".to_string())
            }
            crate::connect::RegisterSessionError::Capacity => {
                malformed("connect session capacity reached; try again later".to_string())
            }
        })?;

    Ok(JsonBody(response))
}

#[cfg(feature = "connect")]
async fn handler_connect_session_delete(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::Path(sid_str): axum::extract::Path<String>,
) -> axum::response::Response {
    use axum::http::StatusCode;

    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }

    match crate::connect::decode_sid(&sid_str) {
        Ok(sid) => {
            let token = match parse_authorization_token(&headers) {
                Ok(Some(token)) => token,
                Ok(None) => {
                    return (
                        StatusCode::UNAUTHORIZED,
                        "connect: missing management token",
                    )
                        .into_response();
                }
                Err(response) => return response,
            };
            if !app
                .connect_bus
                .authorize_management_token(sid, &token)
                .await
            {
                return StatusCode::NOT_FOUND.into_response();
            }
            let removed = app
                .connect_bus
                .clone()
                .terminate_session(sid, crate::connect::CLOSE_REASON_PURGED)
                .await;
            if removed {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        Err(_) => (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
    }
}

#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn parse_connect_ws_query(
    raw: Option<&str>,
) -> Result<routing::ConnectWsQuery, axum::response::Response> {
    use axum::http::StatusCode;
    let mut sid = None;
    let mut role = None;
    if let Some(qs) = raw {
        for pair in qs.split('&') {
            if pair.is_empty() {
                continue;
            }
            let mut parts = pair.splitn(2, '=');
            let key = parts.next().unwrap_or("");
            let value_raw = parts.next().unwrap_or("");
            let value = match urlencoding::decode(value_raw) {
                Ok(decoded) => decoded.into_owned(),
                Err(_) => {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "connect query has invalid encoding",
                    )
                        .into_response());
                }
            };
            match key {
                "sid" => sid = Some(value),
                "role" => role = Some(value),
                "token" => {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "connect query must not include token; use Authorization or Sec-WebSocket-Protocol",
                    )
                        .into_response());
                }
                _ => {}
            }
        }
    }
    fn normalize_role(raw: &str) -> Option<String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "app" => Some("app".to_string()),
            "wallet" => Some("wallet".to_string()),
            _ => None,
        }
    }

    match (sid, role) {
        (Some(sid), Some(role_raw)) => {
            let Some(role) = normalize_role(&role_raw) else {
                return Err(
                    (StatusCode::BAD_REQUEST, "connect query has invalid role").into_response()
                );
            };
            Ok(routing::ConnectWsQuery { sid, role })
        }
        _ => Err((StatusCode::BAD_REQUEST, "connect query missing sid/role").into_response()),
    }
}

const CONNECT_PROTOCOL_TOKEN_PREFIX: &str = "iroha-connect.token.v1.";

#[derive(Debug)]
struct ConnectWsToken {
    token: String,
    protocol: Option<String>,
}

#[derive(Debug)]
struct ProtocolToken {
    token: String,
    protocol: String,
}

#[allow(clippy::result_large_err)]
fn resolve_connect_ws_token(
    headers: &axum::http::HeaderMap,
) -> Result<ConnectWsToken, axum::response::Response> {
    use axum::http::StatusCode;

    let auth_token = parse_authorization_token(headers)?;
    let protocol_token = parse_protocol_token(headers)?;

    if let Some(auth) = auth_token {
        if let Some(proto) = protocol_token.as_ref() {
            if proto.token != auth {
                return Err((
                    StatusCode::BAD_REQUEST,
                    "connect: conflicting tokens in Authorization and Sec-WebSocket-Protocol headers",
                )
                    .into_response());
            }
            return Ok(ConnectWsToken {
                token: auth,
                protocol: Some(proto.protocol.clone()),
            });
        }
        return Ok(ConnectWsToken {
            token: auth,
            protocol: None,
        });
    }

    if let Some(proto) = protocol_token {
        return Ok(ConnectWsToken {
            token: proto.token,
            protocol: Some(proto.protocol),
        });
    }

    Err((
        StatusCode::BAD_REQUEST,
        "connect: missing token; send Authorization: Bearer <token> or Sec-WebSocket-Protocol: iroha-connect.token.v1.<base64url>",
    )
        .into_response())
}

#[cfg(all(test, feature = "connect"))]
mod connect_token_tests {
    use axum::http::{HeaderMap, HeaderName, StatusCode, header};

    use super::{connect_remote_ip_from_headers, parse_connect_ws_query, resolve_connect_ws_token};

    #[test]
    fn connect_query_rejects_token_param() {
        let err = parse_connect_ws_query(Some("sid=abc&role=app&token=deadbeef"))
            .expect_err("token param should be rejected");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn connect_query_rejects_invalid_role() {
        let err = parse_connect_ws_query(Some("sid=abc&role=operator"))
            .expect_err("invalid role should be rejected");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn connect_query_accepts_case_insensitive_role() {
        let ok = parse_connect_ws_query(Some("sid=abc&role=Wallet"))
            .expect("case-insensitive role should be accepted");
        assert_eq!(ok.role, "wallet");
    }

    #[test]
    fn resolve_connect_ws_token_requires_headers() {
        let headers = HeaderMap::new();
        let err = resolve_connect_ws_token(&headers).expect_err("missing token should fail");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn resolve_connect_ws_token_accepts_bearer() {
        let mut headers = HeaderMap::new();
        headers.insert(header::AUTHORIZATION, "Bearer test-token".parse().unwrap());
        let token = resolve_connect_ws_token(&headers).expect("bearer token ok");
        assert_eq!(token.token, "test-token");
        assert!(token.protocol.is_none());
    }

    #[test]
    fn connect_remote_ip_requires_injected_header() {
        let headers = HeaderMap::new();
        let err = connect_remote_ip_from_headers(&headers).expect_err("missing remote addr");
        assert_eq!(err, "connect: remote addr unavailable");
    }

    #[test]
    fn connect_remote_ip_accepts_valid_injected_header() {
        let mut headers = HeaderMap::new();
        headers.insert(
            HeaderName::from_static(crate::limits::REMOTE_ADDR_HEADER),
            "203.0.113.7".parse().unwrap(),
        );
        let ip = connect_remote_ip_from_headers(&headers).expect("remote addr");
        assert_eq!(ip.to_string(), "203.0.113.7");
    }

    #[test]
    fn connect_remote_ip_rejects_invalid_injected_header() {
        let mut headers = HeaderMap::new();
        headers.insert(
            HeaderName::from_static(crate::limits::REMOTE_ADDR_HEADER),
            "not-an-ip".parse().unwrap(),
        );
        let err = connect_remote_ip_from_headers(&headers).expect_err("invalid remote addr");
        assert_eq!(err, "connect: remote addr unavailable");
    }
}

#[allow(clippy::result_large_err)]
fn parse_authorization_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<String>, axum::response::Response> {
    use axum::http::{StatusCode, header};

    let Some(value) = headers.get(header::AUTHORIZATION) else {
        return Ok(None);
    };
    let value_str = value
        .to_str()
        .map_err(|_| {
            (
                StatusCode::BAD_REQUEST,
                "connect: invalid authorization header",
            )
                .into_response()
        })?
        .trim();
    let mut parts = value_str.split_whitespace();
    let scheme = parts.next().unwrap_or_default();
    let token = parts.next().unwrap_or("");
    if parts.next().is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: malformed authorization header",
        )
            .into_response());
    }
    if !scheme.eq_ignore_ascii_case("bearer") {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: authorization header must use Bearer scheme",
        )
            .into_response());
    }
    let token = token.trim();
    if token.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: bearer token is empty").into_response());
    }
    Ok(Some(token.to_owned()))
}

#[allow(clippy::result_large_err)]
fn parse_protocol_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<ProtocolToken>, axum::response::Response> {
    use axum::http::{StatusCode, header};

    let mut values_iter = headers.get_all(header::SEC_WEBSOCKET_PROTOCOL).iter();
    let Some(first_value) = values_iter.next() else {
        return Ok(None);
    };
    for value in std::iter::once(first_value).chain(values_iter) {
        let value_str = value
            .to_str()
            .map_err(|_| {
                (
                    StatusCode::BAD_REQUEST,
                    "connect: invalid Sec-WebSocket-Protocol header",
                )
                    .into_response()
            })?
            .trim();
        for entry in value_str.split(',') {
            let candidate = entry.trim();
            if let Some(encoded) = candidate.strip_prefix(CONNECT_PROTOCOL_TOKEN_PREFIX) {
                let token = decode_protocol_token(encoded)?;
                return Ok(Some(ProtocolToken {
                    token,
                    protocol: candidate.to_string(),
                }));
            }
        }
    }
    Ok(None)
}

#[allow(clippy::result_large_err)]
fn decode_protocol_token(encoded: &str) -> Result<String, axum::response::Response> {
    use axum::http::StatusCode;
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};

    let bytes = B64.decode(encoded).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: invalid protocol token encoding",
        )
            .into_response()
    })?;
    if bytes.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: protocol token is empty").into_response());
    }
    String::from_utf8(bytes).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: protocol token must be valid utf-8",
        )
            .into_response()
    })
}

#[cfg(feature = "connect")]
async fn handler_connect_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> axum::response::Response {
    use axum::http::StatusCode;

    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }

    let bus = app.connect_bus.clone();
    if let Some(raw) = raw_query.as_deref() {
        let mut sid_query = None;
        for pair in raw.split('&') {
            if pair.is_empty() {
                continue;
            }
            let mut parts = pair.splitn(2, '=');
            let key = parts.next().unwrap_or_default();
            let value = parts.next().unwrap_or_default();
            if key == "sid" {
                sid_query = Some(match urlencoding::decode(value) {
                    Ok(value) => value.into_owned(),
                    Err(_) => {
                        return (StatusCode::BAD_REQUEST, "connect: invalid sid query")
                            .into_response();
                    }
                });
            }
        }
        if let Some(sid_query) = sid_query {
            let sid = match crate::connect::decode_sid(&sid_query) {
                Ok(sid) => sid,
                Err(_) => return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
            };
            let token = match parse_authorization_token(&headers) {
                Ok(Some(token)) => token,
                Ok(None) => {
                    return (
                        StatusCode::UNAUTHORIZED,
                        "connect: missing management token",
                    )
                        .into_response();
                }
                Err(response) => return response,
            };
            return match bus.session_status(sid, &token).await {
                Some(status) => JsonBody(status).into_response(),
                None => StatusCode::NOT_FOUND.into_response(),
            };
        }
    }

    let status = bus.status().await;
    #[cfg(feature = "telemetry")]
    {
        if app.telemetry.allows_metrics() {
            let metrics = app.telemetry.metrics().await;
            metrics
                .torii_connect_sessions_total
                .set(status.sessions_total as u64);
            metrics
                .torii_connect_sessions_active
                .set(status.sessions_active as u64);
            metrics
                .torii_connect_buffered_sessions
                .set(status.buffered_sessions as u64);
            metrics
                .torii_connect_total_buffer_bytes
                .set(status.total_buffer_bytes as u64);
            metrics
                .torii_connect_dedupe_size
                .set(status.dedupe_size as u64);
            for entry in &status.per_ip_sessions {
                metrics
                    .torii_connect_per_ip_sessions
                    .with_label_values(&[entry.ip.as_str()])
                    .set(entry.sessions as u64);
            }
        }
    }
    let mut public_status = status;
    public_status.per_ip_sessions.clear();
    JsonBody(public_status).into_response()
}

#[cfg(feature = "app_api")]
fn require_signed_alias_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
) -> Result<AccountId, Error> {
    match crate::app_auth::verify_canonical_request(&app.state, headers, method, uri, body, None)? {
        Some(verified) => Ok(verified.account),
        None => Err(Error::Query(
            iroha_data_model::ValidationFail::NotPermitted(
                "signed account headers are required".to_owned(),
            ),
        )),
    }
}

#[cfg(feature = "app_api")]
async fn handler_alias_resolve(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let request: routing::AliasResolveRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    if request.alias.trim().is_empty() {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "alias must not be empty".to_string(),
            ),
        )));
    }

    if torii_signed_visibility_headers_present(&headers) {
        let _ = torii_visibility_account_from_headers(
            &app,
            &headers,
            &method,
            &uri,
            body.as_ref(),
            "v1/aliases/resolve",
        )?;
    }
    let (canonical, alias_label) = parse_account_alias_label_with_catalog(
        request.alias.as_str(),
        &app.state.nexus_snapshot().dataspace_catalog,
    )?;
    let candidate_routes = match resolve_torii_target_alias_routes(app.as_ref(), &alias_label) {
        Ok(routes) => routes,
        Err(queue::RoutingResolveError::NoLaneForDataspace { .. }) => {
            return execute_alias_resolve_unrouted_local_read(&app, canonical, &alias_label);
        }
        Err(error) => {
            return Ok(torii_proxy_error_response(
                StatusCode::SERVICE_UNAVAILABLE,
                "route_unavailable",
                format!("failed to resolve target-alias routes for {alias_label:?}: {error}"),
            ));
        }
    };

    if candidate_routes.len() == 1 {
        return Ok(execute_torii_single_route_read(
            &app,
            candidate_routes[0],
            ToriiReadEndpointV1::AliasResolve,
            Vec::new(),
            None,
            body.to_vec(),
        )
        .await);
    }

    Ok(torii_proxy_error_response(
        StatusCode::CONFLICT,
        "route_conflict",
        "multiple routes matched the alias dataspace",
    ))
}

#[cfg(feature = "app_api")]
async fn handler_alias_resolve_index(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let _request: routing::AliasResolveIndexRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    let visibility = torii_visibility_account_from_headers(
        &app,
        &headers,
        &method,
        &uri,
        body.as_ref(),
        "v1/aliases/resolve-index",
    )?;
    let candidate_routes = torii_all_dataspace_routes(app.as_ref());
    let (allowed_routes, denied_routes) =
        torii_partition_routes_by_visibility(&app, candidate_routes, &visibility);

    if allowed_routes.len() == 1 && denied_routes == 0 {
        return Ok(execute_torii_single_route_read(
            &app,
            allowed_routes[0],
            ToriiReadEndpointV1::AliasResolveIndex,
            Vec::new(),
            None,
            body.to_vec(),
        )
        .await);
    }

    let collected = match collect_torii_alias_json_payloads(
        &allowed_routes,
        denied_routes,
        "one or more dataspace routes denied the alias-index lookup and no allowed route resolved it",
        |route| {
            execute_torii_read_for_route(
                &app,
                route,
                torii_read_request(
                    ToriiReadEndpointV1::AliasResolveIndex,
                    route,
                    Vec::new(),
                    None,
                    body.to_vec(),
                ),
            )
        },
    )
    .await
    {
        Ok(collected) => collected,
        Err(response) => return Ok(response),
    };
    let diagnostics = collected.diagnostics;
    Ok(merge_with_torii_fanout_headers(diagnostics, || {
        merged_alias_resolve_index_response(
            collected.payloads,
            routed_by_for_routes(&app, &allowed_routes),
            "fanout",
        )
    }))
}

#[cfg(feature = "app_api")]
async fn handler_alias_lookup_by_account(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let request: routing::AliasLookupByAccountRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    if request.account_id.trim().is_empty() {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "account_id must not be empty".to_string(),
            ),
        )));
    }
    let visibility = torii_visibility_account_from_headers(
        &app,
        &headers,
        &method,
        &uri,
        body.as_ref(),
        "v1/aliases/by-account",
    )?;
    let target_account = AccountId::parse_encoded(request.account_id.trim())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "invalid account_id: {err}"
                )),
            ))
        })?
        .into_account_id();
    let candidate_routes = match torii_target_account_routes(app.as_ref(), &target_account) {
        Ok(routes) => routes,
        Err(response) => return Ok(response),
    };
    let (allowed_routes, denied_routes) =
        torii_partition_alias_lookup_routes(&app, candidate_routes, &visibility, &request);

    if allowed_routes.len() == 1 && denied_routes == 0 && !allowed_routes[0].filter_by_permission {
        let route = allowed_routes[0].route;
        return Ok(execute_torii_single_route_read(
            &app,
            route,
            ToriiReadEndpointV1::AliasLookupByAccount,
            Vec::new(),
            None,
            body.to_vec(),
        )
        .await);
    }

    let collected = match collect_torii_alias_lookup_json_payloads(
        &app,
        &allowed_routes,
        denied_routes,
        "one or more dataspace routes denied the alias-by-account lookup and no allowed route returned aliases",
        visibility.caller(),
        |route| {
            execute_torii_read_for_route(
                &app,
                route,
                torii_read_request(
                    ToriiReadEndpointV1::AliasLookupByAccount,
                    route,
                    Vec::new(),
                    None,
                    body.to_vec(),
                ),
            )
        },
    )
    .await
    {
        Ok(collected) => collected,
        Err(response) => return Ok(response),
    };
    let diagnostics = collected.diagnostics;
    let routed_routes = allowed_routes
        .iter()
        .map(|route| route.route)
        .collect::<Vec<_>>();
    Ok(merge_with_torii_fanout_headers(diagnostics, || {
        merged_alias_lookup_by_account_response(
            collected.payloads,
            routed_by_for_routes(&app, &routed_routes),
            "fanout",
            diagnostics.denied_routes,
        )
    }))
}

#[cfg(feature = "app_api")]
fn recipient_lookup_normalize_fi_id(value: &str) -> Option<&'static str> {
    match value.trim().to_ascii_lowercase().as_str() {
        "hbl.sbp" => Some("hbl.sbp"),
        "ubl.sbp" => Some("ubl.sbp"),
        _ => None,
    }
}

#[cfg(feature = "app_api")]
fn recipient_lookup_fi_id_from_alias(alias_fqn: &str) -> Option<&'static str> {
    alias_fqn
        .rsplit_once('@')
        .and_then(|(_, scope)| recipient_lookup_normalize_fi_id(scope))
}

#[cfg(feature = "app_api")]
fn recipient_lookup_alias_is_public(app: &AppState, alias: &AccountAlias) -> bool {
    torii_visible_account_read_routes(app, None)
        .into_iter()
        .any(|route| route.dataspace_id == alias.dataspace)
}

#[cfg(feature = "app_api")]
fn recipient_lookup_signed_alias_access_allowed(
    app: &AppState,
    caller: &AccountId,
    alias: &AccountAlias,
) -> bool {
    torii_visible_account_read_routes(app, Some(caller))
        .into_iter()
        .any(|route| route.dataspace_id == alias.dataspace)
        || {
            let state_view = app.state.view();
            torii_authority_can_resolve_account_alias(state_view.world(), caller, alias)
        }
}

#[cfg(feature = "app_api")]
fn recipient_lookup_permission_gate_response(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
    alias: &AccountAlias,
) -> Result<Option<AxResponse>, Error> {
    if recipient_lookup_alias_is_public(app.as_ref(), alias) {
        return Ok(None);
    }

    let visibility = torii_visibility_account_from_headers(
        app,
        headers,
        method,
        uri,
        body,
        "v1/retail/recipients/lookup",
    )?;
    let Some(caller) = visibility.caller() else {
        return Ok(Some(torii_alias_permission_denied_response(
            "recipient lookup requires canonical request signing for restricted aliases",
        )));
    };

    if recipient_lookup_signed_alias_access_allowed(app.as_ref(), caller, alias) {
        return Ok(None);
    }

    Ok(Some(torii_alias_permission_denied_response(
        "caller lacks account-alias resolve permission for restricted recipient lookup",
    )))
}

#[cfg(feature = "app_api")]
fn recipient_lookup_response(
    resolved: bool,
    account_id: String,
    alias_fqn: String,
    fi_id: String,
    full_name: Option<String>,
) -> Value {
    let mut object = Map::new();
    object.insert("resolved".to_owned(), Value::Bool(resolved));
    object.insert("account_id".to_owned(), Value::String(account_id));
    object.insert("alias_fqn".to_owned(), Value::String(alias_fqn));
    object.insert("fi_id".to_owned(), Value::String(fi_id));
    if resolved {
        if let Some(full_name) = full_name {
            object.insert("full_name".to_owned(), Value::String(full_name));
        }
    }
    Value::Object(object)
}

#[cfg(feature = "app_api")]
fn recipient_lookup_unresolved_response(
    account_id: &str,
    alias_fqn: &str,
    fi_id: &str,
) -> Result<AxResponse, Error> {
    alias_json_response(
        StatusCode::OK,
        recipient_lookup_response(
            false,
            account_id.to_owned(),
            alias_fqn.to_owned(),
            fi_id.to_owned(),
            None,
        ),
    )
}

#[cfg(feature = "app_api")]
fn recipient_lookup_account_identity_matches(
    actual_account_id: Option<&str>,
    expected_account_id: &AccountId,
) -> bool {
    actual_account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(|value| AccountId::parse_encoded(value).ok())
        .map(|parsed| parsed.into_account_id())
        .is_some_and(|actual| actual == *expected_account_id)
}

#[cfg(feature = "app_api")]
fn recipient_lookup_upstream_request_id(headers: &HeaderMap, body: &[u8]) -> String {
    const MAX_REQUEST_ID_LEN: usize = 256;
    headers
        .get("x-request-id")
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty() && value.len() <= MAX_REQUEST_ID_LEN)
        .map(str::to_owned)
        .unwrap_or_else(|| format!("torii-recipient-lookup-{}", blake3_hash(body).to_hex()))
}

#[cfg(feature = "app_api")]
async fn handler_retail_recipient_lookup(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    let request: routing::RetailRecipientLookupRequestDto = norito::json::from_slice(body.as_ref())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
            ))
        })?;
    if request.account_id.trim().is_empty() {
        return Ok(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_recipient_lookup",
            "account_id must not be empty",
        ));
    }
    if request.alias_fqn.trim().is_empty() {
        return Ok(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_recipient_lookup",
            "alias_fqn must not be empty",
        ));
    }

    let requested_account_id_literal = request.account_id.trim().to_owned();
    let (account_id, _, _) = AccountId::parse_encoded(request.account_id.trim())
        .map_err(|err| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "invalid account_id: {err}"
                )),
            ))
        })?
        .into_parts();
    let nexus = app.state.nexus_snapshot();
    let (canonical_alias, alias_label) = parse_account_alias_label_with_catalog(
        request.alias_fqn.as_str(),
        &nexus.dataspace_catalog,
    )?;
    let Some(fi_id) = recipient_lookup_fi_id_from_alias(&canonical_alias) else {
        return Ok(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "unsupported_recipient_lookup_fi",
            "recipient lookup is only available for hbl.sbp and ubl.sbp aliases",
        ));
    };
    if let Some(response) = recipient_lookup_permission_gate_response(
        &app,
        &headers,
        &method,
        &uri,
        body.as_ref(),
        &alias_label,
    )? {
        return Ok(response);
    }

    match resolve_alias_label_on_chain(&app, canonical_alias.clone(), &alias_label)? {
        Some((_, bound_account_id, _)) if bound_account_id == account_id => {}
        _ => {
            return recipient_lookup_unresolved_response(
                &requested_account_id_literal,
                &canonical_alias,
                fi_id,
            );
        }
    }

    let Some(route) = app
        .recipient_lookup
        .routes
        .iter()
        .find(|route| route.fi_id == fi_id)
        .cloned()
    else {
        return Ok(torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "recipient_lookup_not_configured",
            format!("recipient lookup route is not configured for {fi_id}"),
        ));
    };

    let endpoint = format!(
        "{}/v1/retail/recipients/lookup",
        route.base_url.as_str().trim_end_matches('/')
    );
    let upstream_request_id = recipient_lookup_upstream_request_id(&headers, body.as_ref());
    let body = norito::json::to_vec(&routing::RetailRecipientLookupRequestDto {
        account_id: requested_account_id_literal.clone(),
        alias_fqn: canonical_alias.clone(),
    })
    .map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::InternalError(
            err.to_string(),
        ))
    })?;
    let upstream = match reqwest::Client::new()
        .post(endpoint)
        .header("accept", "application/json")
        .header("content-type", "application/json")
        .header("authorization", format!("Bearer {}", route.bearer_token))
        .header("x-request-id", upstream_request_id)
        .body(body)
        .timeout(app.recipient_lookup.request_timeout)
        .send()
        .await
    {
        Ok(response) => response,
        Err(err) => {
            let status = if err.is_timeout() {
                StatusCode::GATEWAY_TIMEOUT
            } else {
                StatusCode::SERVICE_UNAVAILABLE
            };
            return Ok(torii_proxy_error_response(
                status,
                "recipient_lookup_unavailable",
                format!("recipient lookup upstream request failed: {err}"),
            ));
        }
    };
    if !upstream.status().is_success() {
        return Ok(torii_proxy_error_response(
            StatusCode::BAD_GATEWAY,
            "recipient_lookup_rejected",
            format!(
                "recipient lookup upstream returned HTTP {}",
                upstream.status().as_u16()
            ),
        ));
    }
    let upstream_body = match upstream.bytes().await {
        Ok(body) => body,
        Err(err) => {
            return Ok(torii_proxy_error_response(
                StatusCode::BAD_GATEWAY,
                "recipient_lookup_invalid_response",
                format!("recipient lookup upstream response body failed: {err}"),
            ));
        }
    };
    let upstream_payload: Value = match norito::json::from_slice(upstream_body.as_ref()) {
        Ok(payload) => payload,
        Err(err) => {
            return Ok(torii_proxy_error_response(
                StatusCode::BAD_GATEWAY,
                "recipient_lookup_invalid_response",
                format!("recipient lookup upstream response was not valid JSON: {err}"),
            ));
        }
    };
    let Some(upstream_object) = upstream_payload.as_object() else {
        return Ok(torii_proxy_error_response(
            StatusCode::BAD_GATEWAY,
            "recipient_lookup_invalid_response",
            "recipient lookup upstream response was not a JSON object",
        ));
    };

    let full_name = upstream_object
        .get("full_name")
        .and_then(Value::as_str)
        .map(str::trim)
        .map(str::to_owned)
        .filter(|name| !name.is_empty());
    let confirmed_fi_id = upstream_object
        .get("fi_id")
        .and_then(Value::as_str)
        .and_then(recipient_lookup_normalize_fi_id);
    let confirmed = upstream_object.get("resolved") == Some(&Value::Bool(true))
        && recipient_lookup_account_identity_matches(
            upstream_object.get("account_id").and_then(Value::as_str),
            &account_id,
        )
        && upstream_object
            .get("alias_fqn")
            .and_then(Value::as_str)
            .is_some_and(|alias| alias.eq_ignore_ascii_case(&canonical_alias))
        && confirmed_fi_id == Some(fi_id)
        && full_name.is_some();
    alias_json_response(
        StatusCode::OK,
        recipient_lookup_response(
            confirmed,
            requested_account_id_literal,
            canonical_alias,
            fi_id.to_owned(),
            full_name,
        ),
    )
}

#[cfg(feature = "app_api")]
async fn handler_asset_alias_resolve(
    State(app): State<SharedAppState>,
    NoritoJson(request): NoritoJson<routing::AssetAliasResolveRequestDto>,
) -> Result<AxResponse, Error> {
    let alias_literal = request.alias.trim();
    if alias_literal.is_empty() {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(
                "asset alias must not be empty".to_string(),
            ),
        )));
    }

    let alias = AssetDefinitionAlias::from_str(alias_literal).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
        ))
    })?;

    let world = app.state.world_view();
    let now_ms = routing::asset_alias_observation_time_ms(app.state.as_ref());
    let Some(definition_id) = world.asset_definition_id_by_alias_at(&alias, now_ms) else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    let Ok(definition) = world.asset_definition(&definition_id) else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    let alias_binding = world
        .asset_definition_alias_bindings()
        .get(&definition_id)
        .map(|binding| routing::asset_alias_binding_dto(binding, now_ms));
    let logo = definition
        .logo()
        .as_ref()
        .map(|uri| uri.as_ref().to_owned());
    asset_alias_resolve_ok(
        alias.as_ref(),
        &definition_id.to_string(),
        definition.name(),
        alias_binding,
        definition.description().clone(),
        logo,
        "world_state",
    )
}

#[cfg(feature = "app_api")]
fn execute_contract_alias_resolve_local_read(
    app: &SharedAppState,
    request: &routing::ContractAliasResolveRequestDto,
) -> Result<AxResponse, Error> {
    let Some((contract_alias, contract_address, binding, dataspace_alias)) =
        resolve_contract_alias_on_chain(app, &request.contract_alias)?
    else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };

    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;
    contract_alias_resolve_ok(
        contract_alias.as_ref(),
        contract_address.as_ref(),
        &dataspace_alias,
        binding
            .as_ref()
            .map(|record| routing::contract_alias_binding_dto(record, now_ms)),
        "world_state",
    )
}

#[cfg(feature = "app_api")]
async fn handler_contract_alias_resolve(
    State(app): State<SharedAppState>,
    NoritoJson(request): NoritoJson<routing::ContractAliasResolveRequestDto>,
) -> Result<AxResponse, Error> {
    let alias = ContractAlias::from_str(request.contract_alias.trim()).map_err(|err| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(err.to_string()),
        ))
    })?;
    if let Some(route) = torii_contract_target_read_route(app.as_ref(), None, Some(&alias)) {
        let body = norito::json::to_vec(&request).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                "failed to encode routed contract alias resolve request: {error}"
            )))
        })?;
        return Ok(execute_torii_single_route_read(
            &app,
            route,
            ToriiReadEndpointV1::ContractAliasResolve,
            Vec::new(),
            None,
            body,
        )
        .await
        .into_response());
    }

    execute_contract_alias_resolve_local_read(&app, &request)
}

