fn normalise_alias(input: &str) -> String {
    input
        .chars()
        .filter(|c| !c.is_ascii_whitespace())
        .map(|c| c.to_ascii_uppercase())
        .collect()
}

#[cfg(feature = "app_api")]
fn tx_history_reject(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> AxResponse {
    let payload = ErrorEnvelope::new(code, message.into());
    (status, utils::NoritoBody(payload)).into_response()
}

#[cfg(feature = "app_api")]
fn tx_history_alias_resolution_error_message(err: &Error) -> String {
    match err {
        Error::AppConflict { message, .. } if !message.trim().is_empty() => message.clone(),
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(message),
        ))
        | Error::Query(iroha_data_model::ValidationFail::InternalError(message))
            if !message.trim().is_empty() =>
        {
            message.clone()
        }
        _ => err.to_string(),
    }
}

#[cfg(feature = "app_api")]
fn tx_history_alias_resolution_reject(err: Error) -> AxResponse {
    let (status, code) = match &err {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(_),
        )) => (StatusCode::BAD_REQUEST, "tx_history_alias_invalid"),
        Error::AppConflict { .. } => (StatusCode::CONFLICT, "tx_history_alias_conflict"),
        _ => (
            StatusCode::INTERNAL_SERVER_ERROR,
            "tx_history_alias_resolution_failed",
        ),
    };
    tx_history_reject(
        status,
        code,
        tx_history_alias_resolution_error_message(&err),
    )
}

#[cfg(feature = "app_api")]
fn decode_tx_history_jwt_json_part(encoded: &str, error: &'static str) -> Result<Value, String> {
    let bytes = URL_SAFE_NO_PAD
        .decode(encoded.as_bytes())
        .map_err(|_| error.to_string())?;
    norito::json::from_slice(&bytes).map_err(|_| error.to_string())
}

#[cfg(feature = "app_api")]
fn tx_history_jwt_string_claim(
    claims: &Map,
    field: &'static str,
) -> Result<Option<String>, String> {
    match claims.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => value
            .as_str()
            .map(ToString::to_string)
            .ok_or_else(|| "invalid JWT payload".to_string())
            .map(Some),
    }
}

#[cfg(feature = "app_api")]
fn tx_history_jwt_u64_claim(claims: &Map, field: &'static str) -> Result<Option<u64>, String> {
    match claims.get(field) {
        None | Some(Value::Null) => Ok(None),
        Some(value) => value
            .as_u64()
            .ok_or_else(|| "invalid JWT payload".to_string())
            .map(Some),
    }
}

#[cfg(feature = "app_api")]
fn tx_history_jwt_audience_claim(claims: &Map) -> Result<Option<TxHistoryAudienceClaim>, String> {
    match claims.get("aud") {
        None | Some(Value::Null) => Ok(None),
        Some(value) => {
            if let Some(audience) = value.as_str() {
                return Ok(Some(TxHistoryAudienceClaim::Single(audience.to_string())));
            }
            let Some(values) = value.as_array() else {
                return Err("invalid JWT payload".to_string());
            };
            let mut audiences = Vec::with_capacity(values.len());
            for value in values {
                let Some(audience) = value.as_str() else {
                    return Err("invalid JWT payload".to_string());
                };
                audiences.push(audience.to_string());
            }
            Ok(Some(TxHistoryAudienceClaim::Multiple(audiences)))
        }
    }
}

#[cfg(feature = "app_api")]
fn decode_tx_history_jwt_claims(
    auth_header: &str,
    jwt: &TxHistoryJwtConfig,
) -> Result<TxHistoryJwtClaims, String> {
    let token = auth_header
        .trim()
        .strip_prefix("Bearer ")
        .or_else(|| auth_header.trim().strip_prefix("bearer "))
        .ok_or_else(|| "Authorization header must use Bearer token".to_string())?;
    let key = jwt.key.decoding_key(jwt.algorithm)?;
    let mut parts = token.split('.');
    let header_part = parts.next().filter(|part| !part.is_empty());
    let claims_part = parts.next().filter(|part| !part.is_empty());
    let signature_part = parts.next().filter(|part| !part.is_empty());
    if header_part.is_none()
        || claims_part.is_none()
        || signature_part.is_none()
        || parts.next().is_some()
    {
        return Err("invalid JWT".to_string());
    }
    let header_part = header_part.expect("checked above");
    let claims_part = claims_part.expect("checked above");
    let signature_part = signature_part.expect("checked above");
    let header = decode_tx_history_jwt_json_part(header_part, "invalid JWT payload")?;
    let header_object = header
        .as_object()
        .ok_or_else(|| "invalid JWT payload".to_string())?;
    let header_algorithm = header_object
        .get("alg")
        .and_then(Value::as_str)
        .and_then(parse_tx_history_jwt_algorithm)
        .ok_or_else(|| "JWT algorithm does not match Torii tx_history configuration".to_string())?;
    if header_algorithm != jwt.algorithm {
        return Err("JWT algorithm does not match Torii tx_history configuration".to_string());
    }
    let signed_message = format!("{header_part}.{claims_part}");
    let signature_valid = jsonwebtoken::crypto::verify(
        signature_part,
        signed_message.as_bytes(),
        &key,
        jwt.algorithm,
    )
    .map_err(|_| "invalid JWT".to_string())?;
    if !signature_valid {
        return Err("invalid JWT".to_string());
    }
    let claims_value = decode_tx_history_jwt_json_part(claims_part, "invalid JWT payload")?;
    let claims_object = claims_value
        .as_object()
        .ok_or_else(|| "invalid JWT payload".to_string())?;
    let claims = TxHistoryJwtClaims {
        sub: tx_history_jwt_string_claim(claims_object, "sub")?,
        dataspace_id: tx_history_jwt_string_claim(claims_object, "dataspace_id")?,
        exp: tx_history_jwt_u64_claim(claims_object, "exp")?,
        nbf: tx_history_jwt_u64_claim(claims_object, "nbf")?,
        iss: tx_history_jwt_string_claim(claims_object, "iss")?,
        aud: tx_history_jwt_audience_claim(claims_object)?,
    };

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| "system clock is before UNIX_EPOCH".to_string())?
        .as_secs();
    let exp = claims.exp.ok_or_else(|| "missing exp claim".to_string())?;
    if exp <= now {
        return Err("JWT expired".to_string());
    }
    if let Some(nbf) = claims.nbf
        && now < nbf
    {
        return Err("JWT is not yet valid".to_string());
    }
    if let Some(expected_issuer) = jwt.issuer.as_deref() {
        let actual_issuer = claims
            .iss
            .as_deref()
            .ok_or_else(|| "missing iss claim".to_string())?;
        if actual_issuer.trim() != expected_issuer {
            return Err("invalid JWT issuer".to_string());
        }
    }
    if let Some(expected_audience) = jwt.audience.as_deref() {
        let matches = claims.aud.as_ref().is_some_and(|audience| match audience {
            TxHistoryAudienceClaim::Single(value) => value.trim() == expected_audience,
            TxHistoryAudienceClaim::Multiple(values) => {
                values.iter().any(|value| value.trim() == expected_audience)
            }
        });
        if !matches {
            return Err("invalid JWT audience".to_string());
        }
    }

    Ok(claims)
}

#[cfg(feature = "app_api")]
fn resolve_tx_history_alias_account_id(
    app: &SharedAppState,
    alias_input: &str,
) -> Result<Option<AccountId>, Error> {
    if let Some((_, account_id, _)) = resolve_alias_on_chain(app, alias_input)? {
        return Ok(Some(account_id));
    }

    Ok(app
        .iso_bridge
        .as_ref()
        .and_then(|runtime| runtime.resolve_account(alias_input)))
}

#[cfg(feature = "app_api")]
fn tx_history_viewer_from_headers(
    app: &SharedAppState,
    headers: &HeaderMap,
) -> Result<TxHistoryViewerContext, AxResponse> {
    let Some(jwt) = app.tx_history_access_policy.jwt.as_ref() else {
        return Err(tx_history_reject(
            StatusCode::SERVICE_UNAVAILABLE,
            "tx_history_auth_unavailable",
            "transaction history bearer auth is not configured",
        ));
    };
    let auth_header = headers
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .ok_or_else(|| {
            tx_history_reject(
                StatusCode::UNAUTHORIZED,
                "tx_history_authorization_missing",
                "missing Authorization header",
            )
        })?;
    let claims = decode_tx_history_jwt_claims(auth_header, jwt).map_err(|message| {
        tx_history_reject(
            StatusCode::UNAUTHORIZED,
            "tx_history_authorization_invalid",
            message,
        )
    })?;
    let subject = claims
        .sub
        .as_deref()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            tx_history_reject(
                StatusCode::UNAUTHORIZED,
                "tx_history_subject_missing",
                "missing sub claim",
            )
        })?;
    let dataspace_id = claims
        .dataspace_id
        .as_deref()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            tx_history_reject(
                StatusCode::UNAUTHORIZED,
                "tx_history_dataspace_missing",
                "missing dataspace_id claim",
            )
        })?;

    let canonical_account_id = AccountId::parse_encoded(subject.trim())
        .ok()
        .map(iroha_data_model::account::ParsedAccountId::into_account_id);
    let alias_candidates = if canonical_account_id.is_some() {
        Vec::new()
    } else {
        let nexus = app.state.nexus_snapshot();
        match canonical_tx_history_subject_alias(&nexus.dataspace_catalog, &subject) {
            Ok(Some(alias)) => vec![alias],
            Ok(None) => {
                return Err(tx_history_reject(
                    StatusCode::UNAUTHORIZED,
                    "tx_history_subject_invalid",
                    "sub claim must be a canonical account id or account alias literal",
                ));
            }
            Err(err) => return Err(tx_history_alias_resolution_reject(err)),
        }
    };
    let is_mandatory_alias = alias_candidates.iter().any(|alias| {
        app.tx_history_access_policy
            .is_mandatory_alias(&dataspace_id, alias)
    });

    let mut dedupe = HashSet::new();
    let mut account_ids = Vec::new();

    if let Some(account_id) = canonical_account_id {
        if dedupe.insert(account_id.to_string()) {
            account_ids.push(account_id);
        }
    }

    for alias in &alias_candidates {
        match resolve_tx_history_alias_account_id(app, alias) {
            Ok(Some(account_id)) => {
                let key = account_id.to_string();
                if dedupe.insert(key) {
                    account_ids.push(account_id);
                }
            }
            Ok(None) => {}
            Err(err) => {
                return Err(tx_history_alias_resolution_reject(err));
            }
        }
    }

    if account_ids.is_empty() && !is_mandatory_alias {
        return Err(tx_history_reject(
            StatusCode::FORBIDDEN,
            "tx_history_requester_unbound",
            "requester is not bound to a visible transaction account",
        ));
    }

    Ok(TxHistoryViewerContext {
        subject,
        dataspace_id,
        alias_candidates,
        account_ids,
        is_mandatory_alias,
    })
}

const LEDGER_HEADER_PAGE_CAP: u64 = 512;

#[derive(
    Debug,
    Clone,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoSerialize,
    norito::derive::NoritoDeserialize,
)]
struct StateRootResponse {
    height: u64,
    block_hash: HashOf<BlockHeader>,
    /// State root if available (from commit QC or result Merkle root).
    state_root: iroha_crypto::Hash,
    /// Source of the state root for observability (`commit_qc` or `result_merkle_root`).
    source: String,
    /// Commit QC payload when available for attestation (subject hash, bitmap, aggregate sig).
    commit_qc: Option<iroha_data_model::consensus::Qc>,
}

#[derive(
    Debug,
    Clone,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoSerialize,
    norito::derive::NoritoDeserialize,
)]
struct StateProofResponse {
    height: u64,
    block_hash: HashOf<BlockHeader>,
    state_root: iroha_crypto::Hash,
    commit_qc: iroha_data_model::consensus::Qc,
}

async fn handler_ledger_headers(
    State(app): State<SharedAppState>,
    crate::NoritoQuery(window): crate::NoritoQuery<routing::HistoryWindowQuery>,
    headers: axum::http::HeaderMap,
) -> Result<Response, Error> {
    let accept = headers.get(axum::http::header::ACCEPT);
    let format = match crate::utils::negotiate_response_format(accept) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };

    let current_height = u64::try_from(app.state.committed_height()).unwrap_or(u64::MAX);
    let start_height = match window.from {
        Some(0) => return Err(conversion_error("from must be at least 1".to_owned())),
        Some(from) => {
            if current_height == 0 {
                from
            } else {
                from.min(current_height)
            }
        }
        None => current_height,
    };
    let limit = window
        .limit
        .filter(|&lim| lim > 0)
        .unwrap_or(LEDGER_HEADER_PAGE_CAP)
        .min(LEDGER_HEADER_PAGE_CAP)
        .min(usize::MAX as u64) as usize;

    let mut headers: Vec<BlockHeader> = Vec::new();
    let mut height = start_height;
    while height >= 1 && headers.len() < limit {
        if height > usize::MAX as u64 {
            return Err(conversion_error(
                "block height exceeds host pointer width".to_owned(),
            ));
        }
        let Some(nz_height) = NonZeroUsize::new(height as usize) else {
            break;
        };
        if let Some(block) = app.state.block_by_height(nz_height) {
            headers.push(block.header());
        } else {
            break;
        }
        if height == 1 {
            break;
        }
        height -= 1;
    }

    match format {
        ResponseFormat::Norito => Ok(NoritoBody(headers).into_response()),
        ResponseFormat::Json => {
            let body = norito::json::to_json_pretty(&headers).map_err(|err| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    err.to_string(),
                ))
            })?;
            let mut resp = Response::new(Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        }
    }
}

async fn handler_ledger_state_root(
    State(app): State<SharedAppState>,
    axum::extract::Path(height): axum::extract::Path<u64>,
    headers: axum::http::HeaderMap,
) -> Result<Response, Error> {
    let accept = headers.get(axum::http::header::ACCEPT);
    let format = match crate::utils::negotiate_response_format(accept) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };
    let height_nz = NonZeroU64::new(height)
        .ok_or_else(|| conversion_error("height must be at least 1".to_owned()))?;
    let Some(height_usize) = NonZeroUsize::new(
        height_nz
            .get()
            .try_into()
            .map_err(|_| conversion_error("height exceeds host pointer width".to_owned()))?,
    ) else {
        return Err(conversion_error("height must be at least 1".to_owned()));
    };

    let Some(block) = app.state.block_by_height(height_usize) else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };
    let block_hash = block.hash();
    let world = app.state.world_view();
    let commit_qc = world.commit_qcs().get(&block_hash).cloned();
    let payload = if let Some(qc) = commit_qc {
        StateRootResponse {
            height,
            block_hash,
            state_root: qc.post_state_root,
            source: "commit_qc".to_owned(),
            commit_qc: Some(qc),
        }
    } else if let Some(result_root) = block.header().result_merkle_root() {
        StateRootResponse {
            height,
            block_hash,
            state_root: iroha_crypto::Hash::prehashed(*result_root.as_ref()),
            source: "result_merkle_root".to_owned(),
            commit_qc: None,
        }
    } else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };

    match format {
        ResponseFormat::Norito => Ok(NoritoBody(payload).into_response()),
        ResponseFormat::Json => {
            let body = norito::json::to_json_pretty(&payload).map_err(|e| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    e.to_string(),
                ))
            })?;
            let mut resp = Response::new(Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        }
    }
}

async fn handler_ledger_state_proof(
    State(app): State<SharedAppState>,
    axum::extract::Path(height): axum::extract::Path<u64>,
    headers: axum::http::HeaderMap,
) -> Result<Response, Error> {
    let accept = headers.get(axum::http::header::ACCEPT);
    let format = match crate::utils::negotiate_response_format(accept) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };
    let height_nz = NonZeroU64::new(height)
        .ok_or_else(|| conversion_error("height must be at least 1".to_owned()))?;
    let Some(height_usize) = NonZeroUsize::new(
        height_nz
            .get()
            .try_into()
            .map_err(|_| conversion_error("height exceeds host pointer width".to_owned()))?,
    ) else {
        return Err(conversion_error("height must be at least 1".to_owned()));
    };

    let Some(block) = app.state.block_by_height(height_usize) else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };
    let block_hash = block.hash();
    // Ledger state proof requires a persisted commit QC; avoid placeholder synthesis.
    let world = app.state.world_view();
    let commit_qc = world
        .commit_qcs()
        .get(&block_hash)
        .cloned()
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::NotFound,
            ))
        })?;
    let payload = StateProofResponse {
        height,
        block_hash,
        state_root: commit_qc.post_state_root,
        commit_qc,
    };

    match format {
        ResponseFormat::Norito => Ok(NoritoBody(payload).into_response()),
        ResponseFormat::Json => {
            let body = norito::json::to_json_pretty(&payload).map_err(|e| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    e.to_string(),
                ))
            })?;
            let mut resp = Response::new(Body::from(body));
            resp.headers_mut().insert(
                axum::http::header::CONTENT_TYPE,
                HeaderValue::from_static("application/json"),
            );
            Ok(resp)
        }
    }
}

async fn handler_block_proof(
    State(app): State<SharedAppState>,
    axum::extract::Path((height, entry_hex)): axum::extract::Path<(u64, String)>,
) -> Result<NoritoBody<BlockProofs>, Error> {
    let block_height = NonZeroU64::new(height)
        .ok_or_else(|| conversion_error("block height must be at least 1".to_owned()))?;
    let normalized = entry_hex.trim_start_matches("0x");
    let entry_hash: HashOf<TransactionEntrypoint> = normalized
        .parse()
        .map_err(|err| conversion_error(format!("invalid entry hash: {err}")))?;

    let proofs = app
        .state
        .block_proofs_for_entry(block_height, entry_hash)
        .map_err(|err| match err {
            BlockProofError::ZeroHeight | BlockProofError::HeightOutOfRange(_) => {
                conversion_error(err.to_string())
            }
            BlockProofError::BlockNotFound(_)
            | BlockProofError::MissingResults(_)
            | BlockProofError::EntrypointNotFound { .. }
            | BlockProofError::ExecutionResultMissing { .. }
            | BlockProofError::MerkleProofUnavailable { .. } => {
                Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                    iroha_data_model::query::error::QueryExecutionFail::NotFound,
                ))
            }
        })?;
    #[cfg(feature = "connect")]
    if app.connect_enabled {
        if let Err(err) = app
            .connect_bus
            .broadcast_block_proof(block_height, &entry_hash, &proofs)
            .await
        {
            iroha_logger::warn!(
                %err,
                height,
                entry_hex = %entry_hex,
                "connect block proof broadcast failed"
            );
        }
    }
    Ok(NoritoBody(proofs))
}

async fn handler_sumeragi_vrf_commit(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    NoritoJson(request): NoritoJson<routing::VrfCommitRequestDto>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    use axum::response::IntoResponse;

    let Some(handle) = app.sumeragi.clone() else {
        return Ok(axum::http::StatusCode::SERVICE_UNAVAILABLE.into_response());
    };

    if app.require_api_token && !app.api_tokens_set.is_empty() {
        let token_hdr = headers.get("x-api-token").and_then(|v| v.to_str().ok());
        let ok = token_hdr
            .as_ref()
            .is_some_and(|token| app.api_tokens_set.contains(*token));
        if !ok {
            return Ok(axum::http::StatusCode::FORBIDDEN.into_response());
        }
    }

    let key = rate_limit_key(
        &headers,
        Some(remote_ip),
        "v1/sumeragi/vrf/commit",
        app.api_token_enforced(),
    );
    if !app.rate_limiter.allow(&key).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }

    routing::handle_post_sumeragi_vrf_commit(handle, request)
}

