    #[cfg(feature = "app_api")]
    fn spawn_pin_registry_metrics_worker(&self, shutdown_signal: ShutdownSignal) {
        if !self.telemetry.allows_metrics() {
            return;
        }

        let state = self.state.clone();
        let telemetry = self.telemetry.clone();

        tokio::spawn(async move {
            const PIN_REGISTRY_METRICS_INTERVAL_SECS: u64 = 30;
            let mut ticker =
                tokio::time::interval(Duration::from_secs(PIN_REGISTRY_METRICS_INTERVAL_SECS));
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

            if let Err(err) = Self::sample_pin_registry_metrics(&state, &telemetry) {
                iroha_logger::error!(
                    ?err,
                    "failed to collect initial SoraFS pin registry metrics snapshot"
                );
            }

            loop {
                tokio::select! {
                    _ = shutdown_signal.receive() => break,
                    _ = ticker.tick() => {
                        if let Err(err) = Self::sample_pin_registry_metrics(&state, &telemetry) {
                            iroha_logger::error!(?err, "failed to collect SoraFS pin registry metrics snapshot");
                        }
                    }
                }
            }
        });
    }

    #[cfg(feature = "app_api")]
    fn sample_pin_registry_metrics(
        state: &Arc<CoreState>,
        telemetry: &routing::MaybeTelemetry,
    ) -> Result<(), crate::sorafs::registry::PinRegistryError> {
        let world = state.world_view();
        let snapshot = crate::sorafs::registry::collect_pin_registry(&world)?;
        crate::sorafs::registry::record_pin_registry_metrics(telemetry, &snapshot);
        Ok(())
    }

    #[cfg(feature = "app_api")]
    fn spawn_por_ingestion_metrics_worker(&self, shutdown_signal: ShutdownSignal) {
        if !self.telemetry.allows_metrics() || !self.sorafs_node.is_enabled() {
            return;
        }

        let telemetry = self.telemetry.clone();
        let sorafs_node = self.sorafs_node.clone();

        tokio::spawn(async move {
            const POR_INGEST_METRICS_INTERVAL_SECS: u64 = 30;
            let mut ticker =
                tokio::time::interval(Duration::from_secs(POR_INGEST_METRICS_INTERVAL_SECS));
            ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

            let mut known_pairs: HashSet<([u8; 32], [u8; 32])> = HashSet::new();

            Self::sample_por_ingestion_metrics(&sorafs_node, &telemetry, &mut known_pairs);

            loop {
                tokio::select! {
                    _ = shutdown_signal.receive() => break,
                    _ = ticker.tick() => {
                        Self::sample_por_ingestion_metrics(
                            &sorafs_node,
                            &telemetry,
                            &mut known_pairs,
                        );
                    }
                }
            }
        });
    }

    #[cfg(feature = "app_api")]
    fn sample_por_ingestion_metrics(
        sorafs_node: &sorafs_node::NodeHandle,
        telemetry: &routing::MaybeTelemetry,
        known_pairs: &mut HashSet<([u8; 32], [u8; 32])>,
    ) {
        let statuses = sorafs_node.por_ingestion_overview();
        let mut active_pairs: HashSet<([u8; 32], [u8; 32])> = HashSet::new();

        telemetry.with_metrics(|metrics| {
            for status in &statuses {
                let pair = (status.manifest_digest, status.provider_id);
                active_pairs.insert(pair);

                let manifest_hex = hex::encode(status.manifest_digest);
                let provider_hex = hex::encode(status.provider_id);
                metrics.record_sorafs_por_ingestion_backlog(
                    &provider_hex,
                    &manifest_hex,
                    status.pending_challenges,
                );
                metrics.record_sorafs_por_ingestion_failures(
                    &provider_hex,
                    &manifest_hex,
                    status.failures_total,
                );
            }
        });

        telemetry.with_metrics(|metrics| {
            for pair in known_pairs.iter() {
                if active_pairs.contains(pair) {
                    continue;
                }
                let manifest_hex = hex::encode(pair.0);
                let provider_hex = hex::encode(pair.1);
                metrics.record_sorafs_por_ingestion_backlog(&provider_hex, &manifest_hex, 0);
                metrics.record_sorafs_por_ingestion_failures(&provider_hex, &manifest_hex, 0);
            }
        });

        *known_pairs = active_pairs;
    }

    fn add_sumeragi_routes(&self, builder: &mut RouterBuilder) {
        let _ = self;
        macro_rules! mount_get {
            ($descriptor:ident, $handler:expr) => {
                builder.route(&route_catalog::sumeragi::$descriptor, catalog_get($handler));
            };
        }

        mount_get!(EVIDENCE_COUNT, handler_sumeragi_evidence_count);
        mount_get!(EVIDENCE_LIST, handler_sumeragi_evidence);
        mount_get!(SCCP_MESSAGE_PROOF, handler_sccp_message_proof);
        mount_get!(SCCP_PROOF_REQUEST, handler_sccp_proof_request);
        mount_get!(SCCP_MESSAGES_RECENT, handler_sccp_messages_recent);
        mount_get!(SCCP_CAPABILITIES, handler_sccp_capabilities);
        mount_get!(SCCP_REGISTRY, handler_sccp_registry);
        mount_get!(VRF_PENALTIES, handler_sumeragi_vrf_penalties);
        mount_get!(VRF_EPOCH, handler_sumeragi_vrf_epoch);
        mount_get!(BRIDGE_FINALITY, handler_bridge_finality_proof);
        mount_get!(BRIDGE_FINALITY_BUNDLE, handler_bridge_finality_bundle);

        #[cfg(feature = "telemetry")]
        {
            mount_get!(STATUS, handler_sumeragi_status);
            mount_get!(DIAGNOSTICS, handler_sumeragi_diagnostics);
            builder.route(
                &route_catalog::sumeragi::STATUS_SSE,
                catalog_get(handler_sumeragi_status_sse)
                    .authenticated_in_handler(HandlerAuthentication::ProtocolHandshake),
            );
            mount_get!(LEADER, handler_sumeragi_leader);
            mount_get!(BLS_KEYS, handler_sumeragi_bls_keys);
            mount_get!(QC, handler_sumeragi_qc);
            mount_get!(CHECKPOINTS, handler_sumeragi_checkpoints);
            mount_get!(COMMIT_CERTIFICATES, handler_sumeragi_commit_qcs);
            mount_get!(VALIDATOR_SETS, handler_sumeragi_validator_sets);
            mount_get!(
                VALIDATOR_SET_BY_HEIGHT,
                handler_sumeragi_validator_set_by_height
            );
            mount_get!(CONSENSUS_KEYS, handler_sumeragi_consensus_keys);
            mount_get!(KEY_LIFECYCLE, handler_sumeragi_key_lifecycle);
            mount_get!(TELEMETRY, handler_sumeragi_telemetry);
            mount_get!(PARAMETERS, handler_sumeragi_params);
            mount_get!(COMMIT_QC, handler_commit_qc);
        }

        let app_state = builder.state().clone();
        builder.route(
            &route_catalog::sumeragi::EVIDENCE_SUBMIT,
            catalog_post(handler_sumeragi_evidence_submit)
                .authenticated_operator(app_state.clone()),
        );
        builder.route(
            &route_catalog::sumeragi::VRF_COMMIT,
            catalog_post(handler_sumeragi_vrf_commit).authenticated_operator(app_state.clone()),
        );
        builder.route(
            &route_catalog::sumeragi::VRF_REVEAL,
            catalog_post(handler_sumeragi_vrf_reveal).authenticated_operator(app_state.clone()),
        );
    }

