    pub(crate) fn record_latest_committed_header_for_test(
        app: &SharedAppState,
        height: u64,
        creation_time_ms: u64,
    ) {
        let durable_blocks_count = app
            .kura
            .exact_durable_blocks_count()
            .expect("test Kura durable boundary must remain readable");
        assert_eq!(
            app.state.committed_height(),
            durable_blocks_count,
            "test block hash journal must match durable Kura height before appending headers"
        );
        let durable_height =
            u64::try_from(durable_blocks_count).expect("durable height fits into u64");
        assert!(
            height > durable_height,
            "latest test header height must advance durable Kura height"
        );

        let mut prev_hash =
            NonZeroUsize::new(durable_height.try_into().expect("height fits usize"))
                .and_then(|height| app.kura.get_block(height))
                .map(|block| block.hash());
        let mut block_hashes = app.state.block_hashes.block();
        let mut latest_header = None;
        for next_height in durable_height.saturating_add(1)..=height {
            let timestamp = if next_height == height {
                creation_time_ms
            } else {
                0
            };
            let block = make_empty_signed_block(next_height, prev_hash, timestamp);
            latest_header = Some(block.header());
            let hash = store_block(app, block);
            block_hashes.push_for_tests(hash);
            prev_hash = Some(hash);
        }
        block_hashes.commit_for_tests();
        if let Some(header) = latest_header {
            app.state.update_latest_block_header_cache_for_tests(header);
        }
    }

    #[test]
    fn pipeline_status_merge_prefers_committed_success_over_cached_rejection() {
        let now = Instant::now();
        let rejection = TransactionRejectionReason::Validation(ValidationFail::TooComplex);
        let mut entry =
            PipelineStatusEntry::at_time(PipelineStatusKind::Rejected, None, Some(rejection), now);
        entry.merge_from_event(PipelineStatusEntry::at_time(
            PipelineStatusKind::Committed,
            NonZeroU64::new(7),
            None,
            now + Duration::from_secs(1),
        ));
        assert_eq!(entry.kind, PipelineStatusKind::Committed);
        assert_eq!(entry.block_height, NonZeroU64::new(7));
        assert!(entry.rejection.is_none());

        entry.merge_from_event(PipelineStatusEntry::at_time(
            PipelineStatusKind::Applied,
            NonZeroU64::new(7),
            None,
            now + Duration::from_secs(2),
        ));
        assert_eq!(entry.kind, PipelineStatusKind::Applied);
        assert_eq!(entry.block_height, NonZeroU64::new(7));
        assert!(entry.rejection.is_none());
    }

    #[test]
    fn pipeline_status_cache_records_transaction_event() {
        let cache = PipelineStatusCache::new();
        let (block, _) = make_signed_block(1, None);
        let tx_hash = block.external_transactions().next().expect("tx").hash();
        let height = NonZeroU64::new(2).expect("height");
        let event = TransactionEvent {
            hash: tx_hash,
            block_height: Some(height),
            lane_id: LaneId::new(1),
            dataspace_id: DataSpaceId::new(1),
            status: TransactionStatus::Approved,
        };
        cache.record_transaction_event(&event);
        let stored = cache.lookup(&tx_hash).expect("entry");
        assert_eq!(stored.kind, PipelineStatusKind::Approved);
        assert_eq!(stored.block_height, Some(height));
        assert!(stored.rejection.is_none());
    }

