    #[cfg(feature = "zk-stark")]
    fn sample_stark_vk_box(
        backend: &str,
        circuit_id: &str,
        hash_fn: u8,
    ) -> iroha_data_model::proof::VerifyingKeyBox {
        let vk_payload = iroha_core::zk_stark::StarkFriVerifyingKeyV1 {
            version: 1,
            circuit_id: circuit_id.to_owned(),
            n_log2: iroha_core::zk_stark::ZK_ACE_STARK_FRI_PRODUCTION_MIN_N_LOG2,
            blowup_log2: iroha_core::zk_stark::ZK_ACE_STARK_FRI_PRODUCTION_MIN_BLOWUP_LOG2,
            fold_arity: 2,
            queries: iroha_core::zk_stark::ZK_ACE_STARK_FRI_PRODUCTION_MIN_QUERIES,
            merkle_arity: 2,
            hash_fn,
        };
        let bytes = norito::to_bytes(&vk_payload).expect("encode stark vk payload");
        iroha_data_model::proof::VerifyingKeyBox::new(backend.to_owned(), bytes)
    }

